(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-reinforcement-learning-from-human-fe-2024"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-1\">一 · 现场：一个正在被奖励模型拖慢的在线服务</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-2\">二 · 旧方案在推理栈上的三笔账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-3\">三 · 无模型偏好梯度：把比较直接变成更新方向</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-4\">四 · 一个具体例子：长尾样本如何抬高单批延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-5\">五 · 为什么非改不可：偏差与部署复杂度是结构性成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-6\">六 · 工程判断的落点：省链路不等于省算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-7\">七 · 负载画像：把“偏好对”翻译成请求形状</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-8\">八 · 批大小与 SLO：实例相关界的工程投影</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-9\">九 · 策略版本与 KV 复用：缓存收益的硬边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-10\">十 · 长尾的三条传导路径与分桶口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-11\">十一 · 方案反过来限制负载：可接纳形状的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-12\">十二 · 测量口径清单与失败模式对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-13\">十三 · 偏好对前向的批形状约束与分桶调度口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-14\">十四 · 从对数概率差到梯度：kernel 的算术骨架</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-15\">十五 · 数值精度阶梯：FP16/BF16 到 FP8 再到 NVFP4</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-16\">十六 · Blackwell 的四个部件如何落在这条梯度上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-17\">十七 · 缓存与重算：策略版本对 KV 复用的硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-18\">十八 · 精度与算法的耦合：为什么量化不能只在前向做</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-19\">十九 · 一个可落地的 kernel 切分与它的账单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-20\">二十 · 免奖励推断策略梯度的精度边界：前向重算、KV 失效与量化盲区</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-21\">二十一 · 显存账本的三个户头：权重、激活、KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-22\">二十二 · 分页与压缩：把 KV 从连续块变成可回收页</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-23\">二十三 · 复用与卸载：策略版本是复用的硬边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-24\">二十四 · 带宽瓶颈在哪：HBM3e 容量与访存强度的对账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-25\">二十五 · 可复算的显存预算：把上面的账拼成一张表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-26\">二十六 · 免奖励推断路径下的显存账本边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-27\">二十七 · 从“每步两次前向”推导出的批调度约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-28\">二十八 · chunked prefill：把长回答的预填切成可抢占的片</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-29\">二十九 · 优先级与抢占：保护“同一策略版本”的一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-30\">三十 · 分离式预填/解码：把 prefill 的抖动从 decode 路径上摘出去</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-31\">三十一 · 尾延迟：从 P50 到 P99 的三个具体手段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-32\">三十二 · KV 复用与策略版本的耦合代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-33\">三十三 · 无奖励模型时的批调度边界：前向次数、KV 版本与长尾分桶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-34\">三十四 · 并行切分：四种轴与偏好优化的前向结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-35\">三十五 · NVLink 5 与 NVSwitch：域内带宽与集合通信的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-36\">三十六 · All-to-All 与 EP：MoE 策略模型的隐藏税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-37\">三十七 · PP 边界与 DP 的错位：谁在等谁</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-38\">三十八 · NIXL 传输与分离式部署：跨节点的那一段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-39\">三十九 · 通信何时成为瓶颈：三个判据与一个工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-40\">四十 · 偏好梯度回传时的通信边界：为何该方案几乎不触碰 TP/EP 的 All-to-All</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-41\">四十一 · 精度塌陷：从“界失效”到可观测信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-42\">四十二 · OOM 与显存账：省掉奖励模型不等于省掉峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-43\">四十三 · 批抖动与尾延迟：两次前向的乘性放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-44\">四十四 · 静默降级：缓存复用与策略版本错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-45\">四十五 · 监控面与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-46\">四十六 · 免奖励推断流水线的失效边界：从精度塌陷到静默降级的诊断与回滚</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-47\">四十七 · 为什么这篇论文的“基准”必须先被拆成两套口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-48\">四十八 · 硬件档位与部署形态：材料给出的边界在哪</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-49\">四十九 · batch、并发与指标：四个指标各自的归属</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-50\">五十 · 数字怎么读：三类不可比的提升</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-51\">五十一 · 缓存与 KV 复用的口径陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-52\">五十二 · 把这篇论文放进可比矩阵的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-53\">五十三 · 免奖励推断方案的口径边界：哪些数字能比，哪些不能</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-54\">五十四 · 迁移的第一道关口：偏好模型假设是否成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-55\">五十五 · 换模型：策略前向成本结构决定迁移代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-56\">五十六 · 换领域：数据覆盖条件与分布偏移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-57\">五十七 · 规模上限：批大小、重复使用与统计效率</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-58\">五十八 · 量化与硬件：材料未覆盖的迁移风险</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-reinforcement-learning-from-human-fe-2024-sec-59\">五十九 · 迁移边界：奖励模型省掉之后，代价挪到了哪里</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:512px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"430.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">从偏好数据集采样成对回答，构造当前策略下的比较样本。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"430.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用策略模型对候选回答计算对数概率，估计成对偏好下的相对优势。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"430.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">以无模型策略梯度形式更新策略参数，不经过奖励模型反向传播。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"430.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按实例相关界控制批大小与更新步长，维持估计方差在可控范围。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"430.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">周期性评估策略在留出偏好对上的胜率，监控长尾样本的估计偏差。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-1\">一 · 现场：一个正在被奖励模型拖慢的在线服务</h3>\n<p>设想一个已经上线的对话产品：NVL72 机柜里跑着策略模型，旁边单独占一组 GPU 跑奖励模型与安全验证器。用户请求进来，策略先出候选回答，候选被送进奖励模型打分，分数回到调度器决定是否重采样、是否拒答。这条链路在 Blackwell 上的真实代价不在算力峰值，而在串联结构：奖励模型的前向必须等策略前向结束、KV 释放之后才能开始，两段推理无法共享同一批 token 的中间状态，于是机柜内出现周期性的空转窗口。奖励模型本身还要常驻显存——一个与策略同量级的打分模型意味着权重、KV 池、激活缓冲都要另算一份，NVL72 的 HBM 被切成两套互不复用的池子。更隐蔽的代价是偏差：奖励模型是在固定偏好数据上拟合出来的静态函数，策略每轮更新后分布已经漂移，奖励分数却仍按旧分布给出，过优化（reward over-optimization）由此产生，表现为胜率评估上升而人工抽检质量下降。</p>\n<p>这就是这篇论文要拆掉的现场。它的出发点不是把奖励模型训得更好，而是问：既然偏好数据本身就是成对比较，为什么还要先把它压缩成一个标量奖励函数、再从标量里反推策略梯度？常规 RLHF 的两段式流程——先拟合奖励模型、再用 PPO 类算法配一个独立价值网络做策略优化——在推理栈上留下三笔账：奖励模型前向的延迟、奖励模型与价值网络的显存、以及奖励推断误差随策略漂移而放大的偏差。论文选择在只有成对偏好样本、不显式拟合奖励函数的条件下直接学策略，并给出依赖实例的样本复杂度与遗憾界。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-2\">二 · 旧方案在推理栈上的三笔账</h3>\n<p>第一笔是延迟账。两段式服务把一次请求拆成策略生成与奖励打分两个串行阶段，端到端延迟近似为两段前向之和加上调度间隙。若把单请求延迟记作 <span class=\"formula\">$$T_{\\text{e2e}} \\approx T_{\\text{policy}}(L_{\\text{out}}) + T_{\\text{reward}}(L_{\\text{out}}) + T_{\\text{handoff}}$$</span>，其中 <span class=\"formula\">$$T_{\\text{handoff}}$$</span> 是 KV 释放、请求重排与跨进程张量搬运的开销。在连续批处理下这段间隙被批内其他请求部分掩盖，但在长尾样本上无法掩盖：一条超长回答让策略阶段独占 SM，奖励阶段只能等它收尾，批内短请求被迫排队，尾延迟被单条样本拉高。第二笔是显存账。奖励模型与价值网络各自持有独立参数与 KV 池，等于在同一机柜里维护三套模型状态；价值网络在 PPO 里还要对每个 token 做前向以估计基线，显存与带宽开销随序列长度线性上升。第三笔是偏差账，也是最难在监控面板上看见的一笔：奖励模型是离线拟合的判别器，策略更新后回答分布偏离训练分布，奖励分数在分布外区域失去校准，策略便朝着奖励模型的漏洞优化。</p>\n<p>把这三笔账放在一起看，旧方案的根本问题不是某个环节慢，而是推理链路被奖励推断人为切成了两段，且第二段携带一个随策略漂移而失效的静态函数。工程上能做的缓解——奖励模型量化、奖励模型与策略共卡、验证器异步化——都只是在分摊成本，没有消除“必须先有奖励函数”这个前提。论文的切入点正在此处：如果偏好比较可以直接作为策略梯度的信号来源，奖励模型这一整段前向、它占的那份显存、以及它带来的分布外偏差，都可以从部署链路里删掉。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-3\">三 · 无模型偏好梯度：把比较直接变成更新方向</h3>\n<p>论文的核心机制是把一条偏好样本 <span class=\"formula\">$$(x, y^+, y^-)$$</span> 看作策略自身两个回答之间的相对优势估计，而不是先映射成奖励再算优势。给定当前策略，正负回答的对数概率之差经 sigmoid 变换得到偏好概率估计，该估计直接加权正回答的对数概率梯度：</p>\n<div class=\"formula\">$$\\nabla_\\theta J(\\theta)=\\mathbb{E}_{(x,y^+,y^-)\\sim\\mathcal{D}}\\left[\\sigma\\!\\left(\\log\\frac{\\pi_\\theta(y^+|x)}{\\pi_\\theta(y^-|x)}\\right)\\nabla_\\theta\\log\\pi_\\theta(y^+|x)\\right]$$</div>\n<p>这个式子的工程含义值得逐项拆开。括号内的 <span class=\"formula\">$$\\log\\pi_\\theta(y^+|x)-\\log\\pi_\\theta(y^-|x)$$</span> 是策略对两个回答的相对偏好，sigmoid 把它压到 (0,1)，充当一个自适应的样本权重：当策略已经明显偏好正回答时权重接近 1，梯度主要强化正回答；当策略判断模糊或反向时权重下降，该样本对更新的推动变弱。整个估计器不经过任何奖励模型的反向传播，也不维护独立价值网络来估基线——基线的作用被“正负成对”这一结构本身吸收掉了，因为比较是相对的，成对差分天然消去了一部分方差。算法侧因此只需要三样东西：偏好数据缓冲、成对比较采样、以及一个只做前向取对数概率的策略模型。</p>\n<p>代价随之转移。旧方案里奖励模型的前向被删掉，但每步更新需要对正回答与负回答各做一次策略前向以取得 token 级对数概率，前向次数随批大小线性增长。更关键的是策略每轮更新后参数变化，上一轮缓存的回答对数概率立即失效，必须重新计算；KV 复用因此受策略版本约束，复用收益随更新频率上升而下降。这与分离式预填/解码里“预填结果可长期复用”的假设正好相反：在这里，缓存的有效期等于一个更新步。工程判断由此变得清晰——省下的是奖励模型的显存与那段串行前向，付出的是策略前向次数的翻倍与缓存命中率的下降，两者需要在批调度层面重新配平。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-4\">四 · 一个具体例子：长尾样本如何抬高单批延迟</h3>\n<p>取一条批内混合了短问答与长文档摘要的偏好批次。短样本的正负回答各几百 token，两次策略前向可以被打进同一组连续批处理波次；长样本的正负回答各数千 token，其 KV 占用在批内挤压其他请求的可用块，且正负两次前向必须串行完成才能得到对数概率之差。由于无模型梯度要求同一条偏好对的正负回答在同一策略版本下取概率，调度器不能把负回答推迟到下一轮再算——那会引入跨版本的比较偏差。于是这一条长样本把整个批的完成时间拖到它的第二次前向结束，批内其他已完成计算的样本只能等待梯度汇总。按长度分桶调度是直接的对策：把长度相近的偏好对放进同一批，使正负两次前向的时长可比，减少批内等待；材料未给出分桶阈值，工程上应以批内最长样本与中位样本的 token 比作为分桶依据，并把超长样本单独成批以避免污染短批的周转。</p>\n<p>这个例子说明论文的推理代价不是均匀分布的：短样本批的吞吐接近纯策略推理，长样本批的延迟由两次前向叠加决定。若沿用旧方案，长样本还要再叠加一次奖励模型前向，三段串行；新方案把它压到两段，但两段都是策略前向，单段成本高于奖励模型的小型判别器。因此在长尾占比高的负载下，省掉奖励模型未必降低尾延迟，收益主要体现在显存占用与服务拓扑的简化上——少一个模型、少一条跨进程链路、少一套独立的批调度器。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-5\">五 · 为什么非改不可：偏差与部署复杂度是结构性成本</h3>\n<p>延迟与显存可以用工程手段摊薄，偏差不行。奖励模型一旦固定，策略优化就变成对一个静态代理目标的最大化，策略越强，越容易找到代理目标的分布外高分区。两段式流程里没有任何机制约束这种漂移，只能靠早停、KL 惩罚、奖励模型定期重训来缓解，而重训又意味着推理栈里多一条模型热更新链路。论文的无模型形式把信号来源换成了当前策略自身的成对比较，偏好概率随策略同步变化，估计器与策略始终处在同一版本上，结构上消除了“奖励函数落后于策略”的时间差。这不是精度上的改进，而是把偏差从部署链路里移除。</p>\n<p>部署复杂度的账同样结构性。旧方案的服务拓扑是策略服务 + 奖励服务 + 验证器服务，三者有各自的批调度、各自的扩缩容策略、各自的 KV 池；跨服务调用引入序列化与网络跳数，在 NVL72 内部还要占用 NVLink 带宽做张量搬运。新方案把奖励信号退化为离线偏好对，推理侧只剩策略前向一条链路，调度器只需管理一种模型的批与 KV。代价是训练侧每步的前向次数上升，且批大小与步长必须按实例相关分析设定、限制同一偏好对重复使用的次数以控制估计偏差——材料未给出具体批大小与步长数值，工程落地需要按梯度估计方差与留出偏好对胜率联合调参。论文本身偏理论，未涉及并行通信、量化部署与硬件档位，NVFP4/FP8 下的采样稳定性没有数据，因此这套简化能否在 Blackwell 上兑现吞吐收益，仍需补充实测。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-6\">六 · 工程判断的落点：省链路不等于省算力</h3>\n<p>把这篇论文放回推理栈的视角，它给出的不是一个更快的采样器，而是一次链路重构：删掉奖励模型前向与验证器推理，把偏好信号从在线打分改为离线成对数据，代价是每步正负回答各一次策略前向、缓存随策略版本失效、长尾样本抬高批延迟。对容量规划的直接含义是显存侧宽松、算力侧吃紧——同一机柜可以容纳更大的策略或更长的 KV，但单位请求的策略前向次数上升，SM 占用时间增加。对 SLO 的含义是尾延迟的构成变了：不再是策略段加奖励段的串行叠加，而是两次策略前向在同一批内的相互等待，分桶调度与批内长度均衡成为控制尾延迟的主要手段。真正的工程判断在于：当奖励模型的判别能力不是瓶颈、而部署链路复杂度与分布外偏差才是痛点时，这条无模型路径值得替换；当长尾占比极高、策略前向本身已是瓶颈时，删掉奖励模型换来的显存与拓扑简化，可能不足以抵消翻倍的前向开销。</p>\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-7\">七 · 负载画像：把“偏好对”翻译成请求形状</h3>\n<p>这套算法在服务侧的请求单元不是单条 prompt，而是一条三元组 (x, y⁺, y⁻)。推理系统必须为同一个 x 同时持有两条回答的 token 级对数概率，才能算出偏好概率估计。因此负载画像的第一层口径是“对级并发”：设在线并发请求数为 C，则策略前向的瞬时在飞序列数为 2C，而不是 C。这个 2 倍系数直接决定 KV 显存占用与批内 token 预算，任何按单序列估算容量的做法都会低估一半。</p>\n<p>第二层口径是长度分布。材料明确输入长度分布未给出，因此工程上必须自建可核查的测量：对偏好数据集按 max(len(y⁺), len(y⁻)) 做分桶直方图，记录 P50/P90/P99 与桶间方差。之所以取两者最大值而非均值，是因为一条样本的前向代价由较长那条回答决定，短回答不会提前释放其在批内的位置。第三层是“对内长度不对称度” r = |len(y⁺) − len(y⁻)| / max(……)，它衡量批内 padding 浪费；r 接近 1 的样本对是吞吐杀手。</p>\n<p>可核查的测量口径应固定为四项：对级到达率 λ（对/秒）、每对 token 总量 T_pair = len(y⁺)+len(y⁻)、批内 token 方差、以及 P99 对延迟。前三项决定吞吐上限，第四项决定 SLO 是否可守。举例：若某桶 P99 的 T_pair 是 P50 的若干倍，则同一批内混入该桶样本会把整批的完成时间拖到最长样本的尺度——这是分桶调度存在的唯一理由，而不是“优化体验”这类空话。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-8\">八 · 批大小与 SLO：实例相关界的工程投影</h3>\n<p>论文的批大小按实例相关分析设定，并需限制同一偏好对重复使用次数以控制估计偏差。这句话在系统侧有两个可操作的约束。其一是统计约束：同一对在连续 K 个更新步内被复用的次数上限 K_max 决定了数据新鲜度需求，进而决定缓冲区的换入换出频率。其二是延迟约束：批大小 B 增大时，单步前向的 token 总量近似线性增长，而单批完成时间由批内最长序列主导，因此</p>\n<div class=\"formula\">$$L_{\\text{batch}} \\approx \\max_{i \\in \\text{batch}} \\bigl(\\text{len}(y_i^+)+\\text{len}(y_i^-)\\bigr)\\Big/\\text{prefill\\_rate} \\;+\\; \\text{fixed\\_overhead}$$</div>\n<p>这个式子说明批延迟对长尾极端敏感：把 B 从较小值翻倍，若新批恰好纳入一条 P99 长样本，延迟跳变远大于 2 倍。SLO 若按 P99 对延迟设定，则有效批大小必须由“该批内最长样本”反推，而不是由平均 token 数反推。工程判断是：以长度分桶后的桶内批为主调度单元，跨桶拼接只在低负载时启用。</p>\n<p>代价面要算清三笔账。显存账：2C 条序列的 KV 占用与 T_pair 成正比，长尾桶的 KV 峰值决定显存水位线。带宽账：每步需读取正负两条回答的全部 KV 以重算对数概率，HBM 读取量随批内 token 总量线性上升，长尾样本使有效带宽利用率下降。功耗账：前向次数随批大小线性增长意味着算力占用随时长膨胀，长尾批的 SM 占用率被少数序列拖住，单位 token 能耗上升。具体例子：一个以短回答为主的桶可以维持高批大小与稳定 P99；一旦与长回答桶混批，P99 由长桶决定，短桶样本白占调度窗口。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-9\">九 · 策略版本与 KV 复用：缓存收益的硬边界</h3>\n<p>每轮更新后策略参数变化，回答的 token 级对数概率必须重算，因此 KV 缓存的有效期被策略版本钉死。设更新周期为 Δt，缓存条目在版本切换时全部失效，则 KV 复用率的上界是“同一版本内被重复访问的 token 比例”。在线服务中若同一 x 的正负回答在一次更新周期内被多次采样（例如为降低方差而重复采样），复用才有意义；跨版本复用为零收益。这直接限制了以 KV 复用为核心的容量规划：不能按“缓存命中率”做长期假设，只能按版本窗口做短周期估算。</p>\n<p>由此产生一个调度权衡：提高更新频率能更快收敛（理论侧要求控制重复使用次数），但压缩了 KV 复用窗口，抬高重算带宽；降低更新频率则相反。可核查口径是“每版本窗口内重算 token 总量 / 总 token 总量”，该比值越高，说明缓存策略越无效，应转向以分桶与批拼接换吞吐，而非继续投入缓存层级。另一个代价是显存碎片：版本切换时旧 KV 集中释放，新 KV 集中申请，若分桶粒度粗，会出现瞬时峰值高于稳态水位的情况。</p>\n<p>具体机制上，正负两条回答共享同一个 x 的 prompt 前缀 KV，这是唯一稳定的复用点——prompt 部分与策略版本无关的部分（若采用固定分词与位置编码）可在版本间保留，而回答部分的 KV 必须重算。工程上应把 KV 池按 prompt 段与回答段分离管理，前者跨版本长驻，后者随版本滚动回收。举例：一条长 prompt 配两条短回答的样本对，其 prompt KV 占比高，复用收益集中在 prompt 段；反之长回答短 prompt 的样本对几乎无复用价值，应优先分桶而非缓存。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-10\">十 · 长尾的三条传导路径与分桶口径</h3>\n<p>长尾样本拉高单批延迟的路径有三条，必须分开测量，否则优化会打错靶。路径一：批内最长序列决定批完成时间，属于调度层问题，解法是长度分桶与批内长度上限。路径二：正负回答各一次前向使前向次数翻倍，长尾样本的 token 总量放大这一倍数效应，属于算力层问题，解法是控制单批 token 预算而非序列数。路径三：估计偏差——长尾样本在偏好数据中稀疏，其对梯度估计的贡献方差大，若为降方差而重复采样，则又回到路径二的算力膨胀。三条路径的代价分别是延迟、吞吐、统计效率，不能用同一个指标衡量。</p>\n<p>分桶口径建议固定为：按 T_pair 的分位数切桶（例如按 P50、P90 切三档），桶内批大小按 token 预算上限反推，桶间不共享批。可核查指标是“桶内批延迟方差 / 桶间批延迟方差”，前者应显著小于后者，否则说明桶切得不对。材料未给出分桶阈值，因此阈值必须由实测直方图确定，而不是拍脑袋取整。另一个口径是“长尾桶占总 token 的比例”，该比例决定长尾桶需要多少专属算力配额；若比例高而配额低，长尾桶会成为全局 P99 的唯一来源。</p>\n<p>具体例子：假设偏好数据中短回答对占多数但 token 总量由少数长回答对贡献，则按序列数分桶会把长尾桶的批大小压得很小、算力利用率低；按 token 预算分桶则能让长尾桶以较小序列数占满预算，短桶以较大序列数占满预算，两者延迟都可控。这就是“负载塑造方案”的一面：分桶策略由长度分布的形状决定，而不是由平均长度决定。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-11\">十一 · 方案反过来限制负载：可接纳形状的边界</h3>\n<p>方案对负载的反向约束体现在三个可量化的边界上。边界一：对级并发上限由 KV 显存除以单对峰值 KV 决定，而单对峰值 KV 由 max(len(y⁺), len(y⁻)) 决定，因此系统能接纳的最大回答长度直接封死了可服务的请求形状。超出该长度的对必须拒绝或降级（截断、分段），这是容量规划必须写进 SLO 的硬约束。边界二：每步前向次数随批大小线性增长，给定算力配额下存在吞吐饱和点，超过该点增加批大小只增加延迟不增加吞吐。边界三：同一偏好对重复使用次数上限限制了数据管线的供给速率，若在线请求的多样性不足，缓冲区会被少数对占满，梯度估计偏差上升。</p>\n<p>这三条边界共同定义了“可接纳负载形状”：一个由 (最大回答长度, 对级并发, 每版本窗口 token 总量) 构成的三维盒子。工程判断是把这个盒子写进准入控制，而不是让调度器在运行时被动拒绝。具体机制上，准入控制应在请求入口按 T_pair 查表估算 KV 与算力占用，超盒即排队或路由到低优先级桶；这与连续批处理的动态拼批互补——前者防过载，后者提利用率。</p>\n<p>代价面：准入控制过严会浪费算力（短样本无法填满批），过松则长尾拖垮 P99。可核查口径是“拒绝率 / 批内 token 填充率”的联合曲线，寻找填充率不再随放宽准入而上升的拐点。举例：若放宽最大回答长度后填充率不升而 P99 显著上升，说明新增负载全是长尾，应停止放宽。材料未给出量化与硬件数据，因此这些边界必须在本机实测，不能从论文的理论界直接外推——理论界给的是样本复杂度，不是吞吐。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-12\">十二 · 测量口径清单与失败模式对照</h3>\n<p>把上述讨论收敛成一张可核查的表，避免用“大概”“一般来说”含糊过去。每一项都对应一个具体机制与一个系统代价。</p>\n<table class=\"mini\"><thead><tr><th>口径</th><th>定义</th><th>对应机制</th><th>代价维度</th></tr></thead><tbody>\n<tr><td>对级并发 C_pair</td><td>在飞偏好对数</td><td>正负各一次前向</td><td>KV 显存、批内 token</td></tr>\n<tr><td>T_pair 直方图</td><td>len(y⁺)+len(y⁻) 分桶</td><td>批延迟由最长样本主导</td><td>P99 延迟</td></tr>\n<tr><td>对内不对称度 r</td><td>长度差 / 较长者</td><td>padding 浪费</td><td>有效算力利用率</td></tr>\n<tr><td>版本窗口重算比</td><td>重算 token / 总 token</td><td>策略更新使 KV 失效</td><td>HBM 带宽</td></tr>\n<tr><td>桶内延迟方差</td><td>同桶批延迟离散度</td><td>分桶调度</td><td>吞吐稳定性</td></tr>\n<tr><td>重复使用次数 K</td><td>同一对跨步复用上限</td><td>估计偏差控制</td><td>数据供给速率</td></tr>\n<tr><td>准入盒子</td><td>(最大长度, 并发, token 总量)</td><td>准入控制</td><td>拒绝率 vs 填充率</td></tr>\n</tbody></table>\n<p>失败模式与口径一一对应：若 T_pair 直方图长尾厚而分桶阈值取自均值，则 P99 失控；若版本窗口重算比接近 1，则缓存投入无回报，应转向分桶；若 K 上限过紧而数据多样性不足，则梯度估计偏差上升，表现为留出偏好对胜率波动加大而非吞吐下降——这是统计侧失败，不能用扩容解决。材料未给出量化方案与硬件档位，因此 NVFP4/FP8 下的采样稳定性不可从本工作外推，需另行实测对数概率的数值一致性。</p>\n<p>最后落在一个具体机制上：准入控制查表估算 T_pair 对应的 KV 与算力占用时，必须把正负两条回答的 KV 相加而非取其一，且必须按 max 长度而非平均长度计费；这个“按最长、按两条”的计费口径，是把论文的对级前向结构翻译成可运营容量模型的唯一正确入口。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-13\">十三 · 偏好对前向的批形状约束与分桶调度口径</h3>\n<p>该方案在推理侧的独特代价不在解码，而在“取对数概率”这一步：每条偏好样本必须对正回答与负回答各做一次策略前向，前向次数随批大小线性增长。设批内样本数为 <span class=\"inline-math\">B</span>，单条样本正负回答 token 数分别为 <span class=\"inline-math\">L⁺</span>、<span class=\"inline-math\">L⁻</span>，则单批前向 token 总量为 <span class=\"inline-math\">Σ(L⁺+L⁻)</span>，批延迟近似由最长样本决定而非均值——这正是长尾拉高单批延迟的机制根源。与常规 RLHF 部署相比，省去奖励模型打分链路后显存与调度复杂度下降，但策略前向的 token 吞吐需求翻倍（正负各一次），KV 复用收益又受策略版本约束：每轮更新后策略参数变化，上一轮缓存的 token 级对数概率不可直接复用，缓存命中率随更新频率单调下降。因此该方案的负载边界是“更新频率 × 批内长度方差”共同决定的，而非单纯的并发数。</p>\n<p>可核查的测量口径应至少覆盖四项：其一，按长度分桶后的桶内批延迟 P50/P99，用于定位长尾样本对单批延迟的抬升幅度；其二，每步有效前向 token 数与缓存命中率（区分“同策略版本复用”与“跨版本失效”两类），量化 KV 复用收益随更新频率的衰减；其三，同一偏好对重复使用次数的分布，因实例相关分析要求限制重复使用以控制估计偏差，重复度上升会同时抬高偏差与缓存压力；其四，留出偏好对胜率与梯度估计方差的联合监控，二者背离时往往意味着分布偏移已使理论界失效。分桶阈值材料未给出，工程上应以桶内长度方差与批延迟 P99 的拐点为准自行标定。</p>\n<table class=\"mini\"><thead><tr><th>负载维度</th><th>对方案的塑造</th><th>方案的反弹限制</th></tr></thead><tbody><tr><td>输入长度分布</td><td>长尾决定单批延迟上界</td><td>需长度分桶，桶内批大小受实例界约束</td></tr><tr><td>并发与批大小</td><td>前向次数随 B 线性增长</td><td>批越大估计方差越低但延迟越高</td></tr><tr><td>更新频率</td><td>决定 KV 缓存可复用窗口</td><td>高频更新使缓存收益趋零</td></tr><tr><td>SLO</td><td>约束 P99 而非均值</td><td>长尾样本须隔离调度或降级采样</td></tr></tbody></table>\n<p>失效条件集中在两处。第一，分布偏移：理论遗憾界依赖偏好模型假设与数据覆盖条件，当线上偏好分布偏离离线偏好对时，样本复杂度结论不再成立，表现为胜率停滞而梯度方差抬升，此时继续加批只会放大偏差而非收敛。第二，数值精度：材料明确未涉及 NVFP4/FP8 量化下的采样稳定性，对数概率之差经 sigmoid 后对低精度尾部的敏感度未经实验验证，量化部署前必须单独标定正负对数概率差的数值误差带，否则偏好概率估计会被量化噪声主导。工程判断上，该方案适合更新频率可控、长度分布可分桶的离线或准在线偏好优化场景；若 SLO 要求严格的在线低延迟，正负双前向的 token 吞吐代价会成为硬约束，需在批调度与缓存策略间显式权衡，而非依赖奖励模型移除带来的显存红利自动兑现。</p>\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-14\">十四 · 从对数概率差到梯度：kernel 的算术骨架</h3>\n<p>这条无模型偏好梯度的计算图极窄：给定一条偏好三元组 (x, y⁺, y⁻)，策略网络对两条回答各做一次前向，取出各自 token 级对数概率之和，做一次减法，过一次 sigmoid，再用标量权重乘到正回答的对数概率梯度上。整个反向只走 y⁺ 这一支，y⁻ 的前向图在减法之后即被丢弃。这意味着 kernel 层面的核心不是矩阵乘，而是两件小事：一是把变长序列的 log-prob 归约成标量，二是把一个标量权重广播回整条序列的梯度。前者是 reduction，后者是 elementwise scale，二者都受显存带宽而非 Tensor Core 算力约束。</p>\n<p>把公式拆开看：</p>\n<div class=\"formula\">$$\\nabla_\\theta J(\\theta)=\\mathbb{E}_{(x,y^+,y^-)\\sim\\mathcal{D}}\\left[\\sigma\\!\\left(\\log\\frac{\\pi_\\theta(y^+|x)}{\\pi_\\theta(y^-|x)}\\right)\\nabla_\\theta\\log\\pi_\\theta(y^+|x)\\right]$$</div>\n<p>逐项解释：内层 $\\log\\pi_\\theta(y^+|x)-\\log\\pi_\\theta(y^-|x)$ 是两个标量之差，符号决定偏好方向，幅度决定梯度权重；$\\sigma(\\cdot)$ 把差值压进 (0,1)，当策略已把正回答概率推得远高于负回答时权重趋近 1 而梯度饱和，当二者接近时权重约 0.5、梯度最活跃——这正是该估计器“自我调节”的来源，也是它不需要价值网络的算术原因。外层 $\\nabla_\\theta\\log\\pi_\\theta(y^+|x)$ 是标准的策略梯度方向，只对正样本求导。工程上要盯的是：这个标量权重在反向时必须与 y⁺ 的每 token 梯度相乘，若用 FP8 存储激活，权重广播的舍入会直接污染整条序列的梯度方向。</p>\n<p>具体代价：一次更新需要 2 次策略前向（正、负各一）加 1 次反向，前向次数随批大小线性增长；而 log-prob 归约需要在序列维上做跨 token 累加，长回答的归约延迟与序列长度成正比，长尾样本因此抬高单批延迟。这是该算法在推理侧最直接的账单。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-15\">十五 · 数值精度阶梯：FP16/BF16 到 FP8 再到 NVFP4</h3>\n<p>这条梯度对精度的敏感点不在矩阵乘，而在两个标量的差与 sigmoid。$\\log\\pi$ 的数值范围随序列长度增长（每 token 负对数概率累加），FP16 的动态范围在长序列上会逼近上限，BF16 用 8 位指数换 7 位尾数，范围够但尾数粗，差值 $\\log\\pi(y^+)-\\log\\pi(y^-)$ 在两条回答概率接近时是两个大数相减，尾数粗会放大抵消误差。工程判断：log-prob 归约与差值计算应留在 FP32 累加器里，只在进入 sigmoid 前降精度。</p>\n<p>FP8 的两条路线（E4M3 与 E5M2）在这里分工不同：E4M3 尾数多、范围窄，适合存激活与权重供 Tensor Core 消费；E5M2 范围宽、尾数少，适合存梯度这类动态范围大的量。但本算法的梯度是“标量权重 × 逐 token 梯度”，权重本身在 (0,1) 内，逐 token 梯度却可能跨数个数量级，直接 E5M2 存梯度会在小梯度处丢有效位，表现为长尾 token 学不动。NVFP4 把尾数压到 3 位、配两级缩放（每 16 元素一个微块缩放因子加一个张量级缩放），在 Blackwell 上以块缩放形式供 Tensor Core 直接消费；对本算法而言，NVFP4 可用于前向的权重与激活以换取吞吐，但 log-prob 归约与 sigmoid 前后必须回到高精度，否则偏好概率估计的偏差会直接进入梯度权重。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>建议精度</th><th>理由</th></tr></thead><tbody><tr><td>策略前向 GEMM</td><td>BF16 / FP8 E4M3 / NVFP4</td><td>吞吐主导，误差由后续归约吸收</td></tr><tr><td>log-prob 序列归约</td><td>FP32 累加</td><td>跨 token 累加，BF16 累加器尾数不足</td></tr><tr><td>对数概率差与 sigmoid</td><td>FP32</td><td>大数相减的抵消误差敏感</td></tr><tr><td>梯度存储与 all-reduce</td><td>BF16 或 FP8 E5M2 + 高精度主副本</td><td>动态范围大，需保留小梯度有效位</td></tr></tbody></table>\n<p>代价面：FP8 前向相对 BF16 在前向算力上翻倍、显存占用减半，但若归约仍在 BF16 累加，长序列的累加误差会随长度线性累积；NVFP4 进一步把权重显存压到四分之一，代价是每层多一次反量化与块缩放因子的读取，这部分是纯带宽开销，在 batch 小、序列长的解码形态下可能吃掉量化收益。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-16\">十六 · Blackwell 的四个部件如何落在这条梯度上</h3>\n<p>tcgen05 是 SM100 的第五代 Tensor Core 指令族，把矩阵乘的累加器从寄存器文件搬到 TMEM（Tensor Memory）。对本算法，前向 GEMM 走 tcgen05 后，累加结果留在 TMEM 而不占寄存器，寄存器压力释放给 log-prob 归约这类逐元素操作，这是实打实的收益：归约 kernel 的 occupancy 不再被 GEMM 的寄存器需求挤压。TMEM 的容量按 CTA 划分，一个 CTA 能驻留的累加块有限，因此 batch 内序列长度差异大时，TMEM 分配会碎片化，长尾样本可能迫使调度器拆小 CTA，吞吐下降。</p>\n<p>2-SM MMA 让两个 SM 协作完成一次更大的 MMA，共享 TMEM 与操作数，等效于把单个 MMA 的 N 维或 K 维做大。在这条梯度上它的价值在于：正负两条回答可以拼进同一个 2-SM MMA 的 batch 维，一次指令同时算出两组 logits，省掉一次 kernel launch 与一次权重读取。代价是 2-SM 协作要求两个 CTA 同步，若正负回答长度差异大，短的那条要等长的那条，负载不均直接体现为 SM 空转。</p>\n<p>第五代 Tensor Core 的块缩放支持让 NVFP4 的微块缩放因子在 MMA 内部被消费，不需要单独的缩放 kernel；这对本算法意味着前向可以真正吃到 4 位精度的算力，但反量化后的 logits 仍需在 FP32 里做 log-softmax 与归约。具体例子：一条 4K token 的正回答，其 log-prob 归约需跨 4K 个 token 累加，若在 BF16 累加器里做，累加到后半段时单个 token 的贡献已小于累加器的 ulp，等效于丢弃尾部 token 的梯度信号——这正是长尾样本“学不动”的数值根源，而非调度问题。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-17\">十七 · 缓存与重算：策略版本对 KV 复用的硬约束</h3>\n<p>每轮更新后策略参数变化，上一轮缓存的 token 级对数概率即失效，因为 $\\pi_\\theta$ 已不是同一个分布。这与常规推理的 KV 复用逻辑冲突：KV cache 缓存的是注意力中间量，只要权重不变就可复用；而本算法需要的是“当前策略下”的 log-prob，权重一变，缓存的对数概率就是旧策略的量，直接拿来算差值会引入策略版本偏差，使梯度权重系统性偏斜。工程上只有两条路：每轮重算正负回答的 log-prob（前向开销随批大小线性增长），或在同一批偏好对上做多次小步更新以摊薄重算成本——后者正是“限制同一偏好对重复使用次数”的算术动机，重复次数越多，估计偏差越大，但重算开销越低，这是一个显式的权衡参数。</p>\n<p>代价量化：设批大小 B、平均序列长 L，每步前向 FLOPs 约与 2BL 成正比（正负各一），反向约再乘一个常数；若每步都重算，则单步延迟由 2B 次前向决定，长尾样本使 L 的分布右偏，单批延迟由最长的样本决定而非平均值。分桶调度把长度相近的样本拼批，能把“最长样本决定延迟”变成“桶内最长决定延迟”，这是稳定吞吐的直接手段。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-18\">十八 · 精度与算法的耦合：为什么量化不能只在前向做</h3>\n<p>该估计器的梯度权重 $\\sigma(\\Delta)$ 是一个标量，它对 $\\Delta$ 的导数在 $\\Delta=0$ 附近最大。若 $\\Delta$ 由低精度 log-prob 相减得到，两条回答概率接近时 $\\Delta$ 的有效位数被抵消吃掉，sigmoid 输出的权重误差被放大到整条序列的梯度上。这不是“量化噪声均匀分布”的常规情形，而是误差集中在决策边界附近——恰好是偏好对最有信息量的地方。因此量化方案必须保证 $\\Delta$ 的计算链路有足够有效位：前向 GEMM 可以用 NVFP4 换吞吐，但 log-softmax 的归约与减法要回到 FP32，sigmoid 后再降精度去乘梯度。</p>\n<p>另一个耦合点是反向：梯度只走 y⁺ 一支，y⁻ 的前向不参与反向，因此 y⁻ 的前向可以用更低精度甚至更低算力档位跑（它只贡献一个标量），而 y⁺ 的前向精度直接决定梯度质量。这种“不对称精度”是该算法在 Blackwell 上可以做的特有优化：把 y⁻ 的前向放到 NVFP4 高吞吐路径，y⁺ 的前向留在 FP8/BF16，反向用 BF16 主副本加 FP8 通信副本。代价是两条路径的 kernel 不同，调度器要维护两套流水线，批内混合会带来流水线气泡。</p>\n<p>失败模式在此处很具体：材料未给出该算法在 NVFP4/FP8 下的采样稳定性数据，因此不能外推“量化后胜率不掉”的结论；可验证的工程判断只有一条——把 $\\Delta$ 的计算锁在 FP32，把 GEMM 的精度当作独立可调旋钮，二者解耦后再谈端到端吞吐。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-19\">十九 · 一个可落地的 kernel 切分与它的账单</h3>\n<p>把一次更新切成四个 kernel：K1 对 y⁺ 做前向 GEMM（tcgen05，累加在 TMEM，输出 logits 降精度存回）；K2 对 y⁻ 做同样前向但走低精度高吞吐路径；K3 对两组 logits 各做 FP32 log-softmax 与序列归约，得到两个标量并算差值、过 sigmoid 得权重 w；K4 以 w 为标量对 y⁺ 的 log-prob 图做反向。K3 是纯带宽 kernel，读的是整条序列的 logits，写的是两个标量，其耗时与 2BL 成正比而与算力无关；K1/K2 是算力 kernel，K4 是算力加带宽混合。四者串行时，K3 成为不可忽视的固定开销，尤其在小 batch 下。</p>\n<p>优化方向由此明确：把 K3 与 K1/K2 做流水重叠（K1 算完一层就喂给 K3 的归约），把 K4 与下一批的 K1 做双缓冲；用 2-SM MMA 把正负两条回答拼进同一指令以减少 launch 开销，但需接受长度不齐带来的等待。账单是：前向次数 2B、反向 1 次、K3 的带宽读放大为 2BL×词表维；显存侧省去了奖励模型与价值网络，但需为两套精度路径各留一份权重副本或做即时反量化，后者每层多一次带宽读。功耗面，低精度路径的 Tensor Core 利用率上升但归约 kernel 的带宽功耗占比上升，整体功耗分布从算力侧向显存侧偏移。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-20\">二十 · 免奖励推断策略梯度的精度边界：前向重算、KV 失效与量化盲区</h3>\n<p>该算法的数值链条极短：正负回答各一次策略前向取对数概率，差值经 sigmoid 得偏好概率，再乘正回答梯度回传。精度敏感点不在矩阵乘，而在<b>对数概率差的动态范围</b>。设正负回答对数概率为 $\\ell^+,\\ell^-$，偏好估计为 $p=\\sigma(\\ell^+-\\ell^-)$，梯度权重即 $p$。当 $\\ell^+-\\ell^-$ 落入大负值区，$p$ 饱和至零，梯度信号被数值下溢吞掉；落入大正值区则权重趋一，估计方差被放大。FP16 下 $\\sigma$ 输入超过约十余即饱和，BF16 指数位宽更宽但尾数仅 7 位，$\\ell$ 本身的累加误差会直接污染差值。工程判断是：logits 归约与 log-softmax 累加应走 FP32，回答级对数概率以 FP32 落盘，仅在 GEMM 主路径用 BF16/FP8。</p>\n<p>Blackwell 的 tcgen05 与 TMEM 改变了这笔账。第五代 Tensor Core 的 2-SM MMA 让两个 SM 共享一次大形状矩阵乘，TMEM 作为累加器驻留片上，减少寄存器往返；对策略前向这是吞吐利好，但对本算法是<b>精度陷阱</b>：若把 log-softmax 的归约也压进低精度累加器，$\\ell^+-\\ell^-$ 的舍入误差会随回答长度线性累积。代价侧，TMEM 容量有限，长回答的 KV 与中间激活争抢片上空间，2-SM 配对又要求两 SM 负载均衡——正负回答长度不齐时，配对退化为单 SM 路径，吞吐回落。长尾样本正是这里的失效条件：一条超长负回答会把整批拖入不均衡配对。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>建议精度</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>策略 GEMM</td><td>BF16/FP8</td><td>长回答尾数累积</td><td>吞吐升，需 FP32 残差</td></tr><tr><td>log-softmax 归约</td><td>FP32</td><td>低精度累加饱和</td><td>占用 TMEM/寄存器</td></tr><tr><td>对数概率差与 sigmoid</td><td>FP32</td><td>差值越界饱和</td><td>可忽略</td></tr><tr><td>KV 复用</td><td>随策略版本失效</td><td>每轮更新后重算</td><td>缓存命中率随步长下降</td></tr></tbody></table>\n<p>KV 复用的收益被策略版本钉死：每步更新后 $\\pi_\\theta$ 变化，旧回答的 token 级对数概率必须重算，缓存只在同一策略版本内的多次采样间有效。步长越大、更新越频繁，KV 复用率越低，前向开销越接近全量重算——这是<b>算法收敛性与推理吞吐的直接对冲</b>。至于 NVFP4，材料未给出量化下采样稳定性数据，不可外推：偏好概率依赖对数概率差的细粒度比较，FP4 的块缩放会把小幅差值抹平，sigmoid 输入失真，梯度权重系统性偏移。落地前须单独验证量化后的胜率漂移，而非假设 Tensor Core 峰值即推理收益。</p>\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-21\">二十一 · 显存账本的三个户头：权重、激活、KV</h3>\n<p>在 Blackwell 上做免奖励推断的偏好优化推理，显存不是一块整账，而是三个性质完全不同的户头。权重是静态常驻：B200 单卡 HBM3e 容量按 192GB 档计，GB200 NVL72 单 GPU 同为 192GB 量级，权重占用等于参数量乘以每参数字节数——FP8 是 1 字节，NVFP4 是 0.5 字节再加每 16 元素一组共享的 E4M3 缩放因子（约 0.5625 字节/参数），外加 layernorm、embedding、输出头这些通常保留高精度的层。激活是瞬态：每步要对正回答与负回答各做一次策略前向取对数概率，前向的中间张量随批内 token 数线性涨，随层数线性涨，但可以在算子间复用 workspace。KV cache 是随策略版本失效的半持久户头——这一点在本算法里被放大：每轮更新后策略参数变了，上一轮缓存的 token 级对数概率与 KV 不再对应当前策略，复用收益随更新频率单调下降。</p>\n<p>把三个户头写成一条预算不等式，是工程上唯一可复算的形式：</p>\n<div class=\"formula\">$$M_{\\text{total}} \\ge \\underbrace{N_{\\text{param}}\\cdot b_w}_{\\text{权重}} + \\underbrace{B_{\\text{tok}}\\cdot L\\cdot h\\cdot b_a\\cdot k}_{\\text{激活}} + \\underbrace{2\\cdot B_{\\text{seq}}\\cdot L_{\\text{ctx}}\\cdot n_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot b_{\\text{kv}}}_{\\text{KV（正+负两条回答）}} + M_{\\text{workspace}}$$</div>\n<p>其中 $B_{\\text{tok}}$ 是批内并发 token 数，$k$ 是激活保存倍数（是否重算决定），系数 2 来自正负回答各一条序列。KV 项里的 2 是本算法特有的：一次前向要同时容纳正例与负例两条回答的上下文，而常规单条生成只算一份。这意味着同样的并发下，偏好优化的 KV 占用是普通解码的两倍，除非把正负回答拼进同一条 packed 序列共享前缀 KV。</p>\n<p>具体例子：一个 70B 级策略模型，FP8 权重约 70GB，NVFP4 约 40GB；若单卡 192GB，剩给激活与 KV 的是 120GB 上下。取 $L_{\\text{ctx}}=8192$、$n_{\\text{kv}}\\cdot d_{\\text{head}}=8192$（GQA 后的等效 KV 宽度）、$b_{\\text{kv}}=1$ 字节（FP8 KV），单条序列 KV 为 $2\\cdot8192\\cdot8192\\cdot1\\approx134$MB，正负两条即 268MB；再乘并发 64，KV 户头就是 17GB 量级。这个数字说明：在长上下文偏好数据上，KV 不是零头，它和激活一起决定了并发上限。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-22\">二十二 · 分页与压缩：把 KV 从连续块变成可回收页</h3>\n<p>连续分配的 KV 池在偏好优化里格外浪费，因为正负回答长度分布不对称——正例往往更长、负例更短，按最大长度预留会把差额全部变成内部碎片。分页机制（PagedAttention 一类）把 KV 切成固定 token 数的块，按需分配、按块回收，块表记录逻辑位置到物理块的映射。收益有两层：一是碎片率从“按最长序列预留”降到“按实际 token 数向上取整到块”，二是块可以在序列结束后立即归还池子，供同一批内其他样本复用。</p>\n<p>压缩走三条路，各有代价。第一是 KV 量化：FP8 KV 把每元素 2 字节压到 1 字节，容量翻倍，代价是注意力分数与 softmax 的数值误差，长上下文下误差累积更明显；NVFP4 KV 更激进，但材料明确指出该工作未涉及 NVFP4/FP8 量化下的采样稳定性，工程落地必须另行验证——尤其是本算法要对数概率做 sigmoid 加权梯度，log-prob 的微小偏差会直接进入梯度估计，量化误差不是“只影响生成质量”而是“影响估计量”。第二是 GQA/MLA 式的结构压缩，减少 KV 头数或把 KV 投影到低秩潜空间，这是模型结构决定的，推理侧只能选不能改。第三是 token 级驱逐（滑动窗口、H2O 式重权保留），代价是不可逆的信息丢失，对需要全序列 log-prob 的偏好优化尤其危险：被驱逐的 token 其对数概率无法精确重算。</p>\n<p>系统代价要算清：分页把块表查询引入注意力 kernel 的寻址路径，块大小选小了表长、选大了碎片回升；典型块大小取 16 或 32 token。吞吐上，分页让并发从“按最长序列”变成“按总块数”，在长度方差大的偏好数据上提升明显；延迟上，块表间接寻址增加少量访存，但相比碎片导致的并发下降是净收益。工程判断：偏好优化场景应默认开启分页，并把正负回答拼成一条 packed 序列共享系统提示与前缀 KV，这是把系数 2 降回 1 的最直接手段。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-23\">二十三 · 复用与卸载：策略版本是复用的硬边界</h3>\n<p>复用在本算法里有三种粒度，收益依次递减。最粗的是前缀复用：同一提示的正负回答共享提示部分的 KV，一次前向算完提示 KV 后两条回答各自续算，省掉一半提示侧计算。中等的是跨步复用：同一批偏好样本在连续多步被重复使用时，若策略未更新则可复用上一轮 KV 与 log-prob；但算法要求每轮更新后重新计算 token 级对数概率，且需限制同一偏好对重复使用次数以控制估计偏差——两条约束叠加，跨步复用的窗口极窄，只在不更新参数的评估步或梯度累积的微步内有效。最细的是算子内复用：正负回答的 log-prob 计算共享同一套 attention workspace 与归一化缓冲，属于 kernel 级优化。</p>\n<p>卸载（offload）把冷 KV 或冷权重搬到主机内存或 NVLink 对端。Blackwell 的 NVLink 5 提供高带宽 GPU 间通路，GB200 NVL72 机架内 72 个 GPU 通过 NVLink 域互联，使得“把 KV 放到邻卡 HBM”比“放回主机 DRAM”更划算——前者带宽高一个量级，后者受 PCIe 限制。卸载的判据是带宽账：一次 KV 换入换出的字节数除以链路带宽，必须小于它所带来的计算节省，否则卸载只是把显存压力换成延迟压力。对偏好优化，权重卸载意义不大（每步都要全量前向），KV 卸载只在超长上下文、低并发、SLO 宽松的场景成立。</p>\n<p>具体例子：若把 64 并发、8192 上下文的 17GB KV 中一半卸载到邻卡，按 NVLink 5 的高带宽量级，换入一次的开销量级在毫秒级，而省下的显存可把并发提到 96；但若 SLO 是严格的 token 间延迟，这笔换入就落在关键路径上，不可接受。复用与卸载的取舍本质是“把显存压力换成带宽压力”，而带宽压力是否可接受，取决于该请求在批调度里是否处于关键路径。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-24\">二十四 · 带宽瓶颈在哪：HBM3e 容量与访存强度的对账</h3>\n<p>容量算完只是第一步，第二步要问：这些字节每步被搬多少次。HBM3e 的容量按 192GB 档、带宽按每 GPU 数 TB/s 量级定性描述（材料未给出具体档位数字，不做外推）。解码阶段是典型的访存受限：每生成一个 token，要把权重全部读一遍（或按层分块读），算术强度极低，因此 token 间延迟近似正比于权重字节数除以 HBM 带宽。偏好优化的前向不是自回归逐 token，而是对整条回答做一次并行前向取 log-prob，算术强度高于解码、低于预填，属于中间态：它的瓶颈既可能是权重带宽（批小、序列短时），也可能是 KV 带宽（批大、序列长时）。</p>\n<p>把这条写成可判据的形式：设批内 token 数 $B_{\\text{tok}}$，权重字节 $W$，KV 字节 $K$，则单步时间下界近似为</p>\n<div class=\"formula\">$$T_{\\text{step}} \\gtrsim \\max\\!\\left(\\frac{W}{BW_{\\text{HBM}}},\\ \\frac{K}{BW_{\\text{HBM}}},\\ \\frac{\\text{FLOPs}}{F_{\\text{peak}}}\\right)$$</div>\n<p>三项谁大谁就是瓶颈。批小的时候第一项主导，此时增大批不降延迟但降单位 token 成本；批大到 KV 项超过权重项时，继续加批只增加 KV 带宽压力，吞吐饱和。这个交叉点就是最优批大小的粗略判据，也是分桶调度的理论依据：长尾样本把 $B_{\\text{tok}}$ 推高，使 KV 项提前主导，单批延迟被拉长——材料明确指出长尾样本会拉高单批延迟，建议按长度分桶调度以稳定吞吐。分桶的本质是把 $B_{\\text{tok}}$ 控制在交叉点附近，让每一步都落在“权重带宽主导、KV 尚未饱和”的区间。</p>\n<p>另一个常被忽略的带宽项是 log-prob 的回写：本算法要把正负回答的 token 级对数概率保留下来供梯度估计，这些中间量若落在 HBM 就要占带宽与容量。工程上应让 log-prob 在 kernel 内完成 sigmoid 加权与梯度累加，只回写标量化的批级梯度，避免 token 级中间张量往返 HBM——这一步省下的带宽往往比调批大小更直接。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-25\">二十五 · 可复算的显存预算：把上面的账拼成一张表</h3>\n<p>下面给出一份可复算的预算模板，参数全部符号化，读者代入自己的模型与并发即可。假设：70B 级策略、NVFP4 权重（含缩放因子按 0.5625 字节/参数）、FP8 KV、上下文 8192、正负回答各一条、并发 $C$、激活按每 token 每层 $h$ 维、保存倍数 $k=2$（含 attention 输出与 MLP 中间）。</p>\n<table class=\"mini\">\n<thead><tr><th>户头</th><th>计算式</th><th>代入示例</th><th>占 192GB 比例</th></tr></thead>\n<tbody>\n<tr><td>权重</td><td>$N\\cdot0.5625$</td><td>70e9×0.5625 ≈ 39.4GB</td><td>约 21%</td></tr>\n<tr><td>激活</td><td>$C\\cdot B_{\\text{tok}}\\cdot L\\cdot h\\cdot b_a\\cdot k$</td><td>按并发 64、每序列 8192 token 量级估算，数十 GB 量级</td><td>随批线性涨</td></tr>\n<tr><td>KV（正+负）</td><td>$2C\\cdot L_{\\text{ctx}}\\cdot n_{\\text{kv}}d_{\\text{head}}\\cdot1$</td><td>64×2×8192×8192×1 ≈ 8.6GB（未计块碎片）</td><td>约 4.5%</td></tr>\n<tr><td>workspace</td><td>按最大 kernel 分块与通信缓冲预留</td><td>数 GB 量级</td><td>固定</td></tr>\n</tbody>\n</table>\n<p>复算要点有三。其一，权重项在小模型上占比低，在大模型上逼近容量上限，此时 KV 与激活的余量被压缩，并发上限由剩余容量反推：$C_{\\max}\\approx(M_{\\text{total}}-W-M_{\\text{ws}})/(\\text{每并发激活}+\\text{每并发 KV})$。其二，激活项里的 $k$ 是重算策略的开关：开启梯度检查点式重算可把 $k$ 降到 1，代价是前向多算一遍，把显存压力换成算力与延迟——在本算法里前向已经是瓶颈（每步正负各一次），重算会进一步拉长单批延迟，需谨慎。其三，KV 项里的系数 2 可通过 packed 序列消掉，这是性价比最高的一步，且不引入数值误差。</p>\n<p>把这张表落到工程判断上：免奖励推断省掉的是奖励模型与验证器那条服务链路的显存与调度复杂度——那是一条独立的模型服务，有自己的权重、KV 与批队列；省掉它意味着整个推理栈只剩策略模型一个户头，调度器不必在奖励打分与策略生成之间做跨服务同步。但代价转移到了策略前向次数上：前向次数随批大小线性增长，长尾样本抬高单批延迟。因此本算法的显存优化重点不在“省容量”，而在“把容量换成并发、把并发换成稳定吞吐”——分页降碎片、packed 序列降 KV 系数、分桶调度控 $B_{\\text{tok}}$、log-prob 就地归约降回写带宽，这四步合起来才是这套账本的落地形态。量化侧的 NVFP4 采样稳定性材料未给出，任何把权重压到 4 比特的部署都必须先验证 log-prob 偏差是否仍在梯度估计可接受范围内，否则省下的显存会被估计方差吃掉。</p>\n\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-26\">二十六 · 免奖励推断路径下的显存账本边界与失效条件</h3>\n<p>省去奖励模型与价值网络后，显存账本从三份权重（策略、奖励、价值）收缩为一份策略权重，但KV侧的压力并未消失，反而因“每步正负各一次前向”被放大。设批内正负样本总token数为$T$、层数$L$、KV头数$H_{kv}$、头维$d$、每元素字节$b$，则单轮KV占用可写为<div class=\"formula\">$$M_{kv}=2\\cdot L\\cdot H_{kv}\\cdot d\\cdot b\\cdot T$$</div>系数2来自K与V两份缓存。以GQA下$H_{kv}d$远小于$H_qd$的情形为例，KV账本主要由$T$与$L$驱动，而非注意力头数；因此长尾样本一旦进入同一批，$T$被少数超长回答拉高，KV峰值随之上抬，单批延迟同步恶化。这正是该方案最直接的显存代价：奖励模型那部分省下来的容量，被正负双前向的激活与KV需求部分抵消。</p>\n<p>更关键的失效条件是缓存复用受策略版本约束。每轮更新后$\\pi_\\theta$变化，token级对数概率必须重算，上一轮写入的KV只在同一策略版本内有效；更新越频繁，分页KV cache的命中率越低，前缀复用与跨批共享的收益被压缩。工程上可把偏好对按长度分桶、限制同一偏好对重复使用次数以控制估计偏差，并把正负回答的前向合并进同一连续批处理批次以摊薄调度开销；但分桶阈值与批大小材料未给出，只能按实例相关界定性设定。若强行用NVFP4/FP8压缩KV以换容量，采样阶段的对数概率数值稳定性未经该工作验证，属于账本之外的额外风险，不能默认成立。</p>\n<table class=\"mini\"><thead><tr><th>账本项</th><th>该方案下的变化</th><th>系统代价落点</th></tr></thead><tbody><tr><td>策略权重</td><td>唯一常驻权重</td><td>容量释放，但单卡仍需容纳全量参数</td></tr><tr><td>奖励/价值权重</td><td>移除</td><td>省去打分前向与调度链路</td></tr><tr><td>KV cache</td><td>正负各一份，随批线性增长</td><td>长尾样本抬高峰值与单批延迟</td></tr><tr><td>激活</td><td>双前向叠加</td><td>批内峰值显存上升</td></tr></tbody></table>\n<p>可复算的预算思路是：先按目标SLO定出单批可接受的$T$上限，再由上式反推$M_{kv}$，剩余容量留给权重与激活；若$M_{kv}$逼近上限，优先做长度分桶而非加大批，因为批大小线性放大前向次数，而分桶只削峰不增总量。卸载策略在此处收益有限——KV按轮失效，卸载到主机再回填的窗口很短，PCIe往返延迟会直接吃掉吞吐。结论落在工程判断上：该方案的显存优势是结构性的（少一份权重与一条服务链路），但其吞吐边界由“策略版本刷新频率×正负双前向×长尾长度分布”三者共同决定，任一维度失控，省下的显存就会被KV峰值与批延迟重新吃掉。</p>\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-27\">二十七 · 从“每步两次前向”推导出的批调度约束</h3>\n<p>免奖励推断的偏好策略梯度把推理侧的成本结构改写成一个很硬的约束：每一步更新必须对正回答与负回答各做一次策略前向，取到 token 级对数概率，二者之差经 sigmoid 得到偏好概率，再以该概率加权正回答的梯度。这意味着一个训练步的最小前向工作量是 2B（B 为批内偏好对数量），且这 2B 次前向必须在同一策略版本下完成——否则正负两侧的对数概率来自不同参数，比值失去意义。连续批处理（continuous batching）在这里的作用不是“把 GPU 喂满”，而是把 2B 次前向压进同一个策略版本的窗口内，让调度器以 iteration 为粒度而非以请求为粒度做准入决策。</p>\n<p>代价可以写成一个简单的准入判据。设单批目标时延为 T_batch，单条回答的平均前向时延为 t_seq(len)，则批内可容纳的偏好对数量受</p>\n<div class=\"formula\">$$B \\le \\frac{T_{\\text{batch}}}{2\\,\\bar{t}_{\\text{seq}}(\\text{len})}\\cdot \\eta_{\\text{pack}}$$</div>\n<p>约束，其中 η_pack 是打包效率（受序列长度方差与 KV 分页碎片影响）。长尾样本直接抬高 t̄_seq，从而压低 B；而 B 又被实例相关分析约束——同一偏好对重复使用次数过多会引入估计偏差，批太小则梯度方差上升。两个方向同时挤压，调度器实际上是在“方差可接受的最小批”和“时延可接受的最大批”之间取交集。工程判断是：先把长度分桶做在采样阶段，让每个桶内的 t_seq 方差收敛，再让连续批处理在桶内做迭代级调度，避免一条超长回答把整批拖到 T_batch 之外。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-28\">二十八 · chunked prefill：把长回答的预填切成可抢占的片</h3>\n<p>偏好对里的回答长度分布通常右偏，长回答的 prefill 阶段是单批延迟的主要来源。chunked prefill 把一条长序列的预填按固定 token 数切片，与 decode 请求混排在同一 iteration 中，使调度器获得“半个回答也能先占位”的粒度。对本算法而言，这一点尤其关键：正负回答必须成对进入同一策略版本，若一条长负回答的 prefill 跨越了参数更新，则该对的比值失效。切片调度让长回答的 prefill 能在若干个 iteration 内完成，而更新节奏被拉长到“最慢切片完成”为止。</p>\n<p>代价体现在两个方向。切片提高了打包效率，吞吐上升；但每个切片都要重读已缓存的 KV 前缀，prefill 的总计算量随切片数增加而略增，且切片边界处的 KV 写入与分页分配带来额外显存带宽开销。一个具体例子：一条 8k token 的负回答被切成 4 片、每片 2k，与若干短正回答的 decode 混排，则这 4 个 iteration 内该批的有效偏好对吞吐被这条样本钉住；若桶内还有三条同类长样本，调度器应把它们错开到不同 iteration，而不是同批并发，否则 T_batch 由最长者决定而其余算力空转。这就是“按长度分桶 + 桶内错峰”的具体含义，材料未给出分桶阈值，工程上以 P95 长度为切点、以 t_seq 方差最小化为准则。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-29\">二十九 · 优先级与抢占：保护“同一策略版本”的一致性</h3>\n<p>连续批处理天然支持请求级优先级，但本算法的优先级不是按用户 SLO 排的，而是按“策略版本一致性”排的。一个偏好对的正负两次前向若被参数更新隔开，就必须整体重算；因此调度器应把成对请求标记为原子单元，赋予高于普通请求的优先级，并在显存压力下优先抢占那些已经跨版本的半成品。抢占的代价是重算：被抢占的回答已写入的 KV 分页可以保留，但 log-prob 必须在当前版本下重新前向，等于把已付出的算力作废。</p>\n<p>抢占策略可以用一个收益判据表达：设被抢占序列已算长度为 l、剩余长度为 L−l，保留 KV 的显存成本为 m(l)，重算成本为 t_seq(L−l)，则抢占收益为正的条件是</p>\n<div class=\"formula\">$$\\text{evict} \\iff m(l) &gt; \\lambda\\cdot t_{\\text{seq}}(L-l)$$</div>\n<p>其中 λ 把显存压力折算为时延当量。工程上的做法是给“跨版本半成品”设一个硬上限：一旦某偏好对的两次前向跨过更新边界，直接丢弃并重新入队，而不是让它在队列里反复被抢占又反复重算——后者会把尾延迟从单批问题放大成队列级抖动。这也是尾延迟压制的主要抓手：尾延迟的来源往往不是单条长样本，而是长样本在版本边界附近被反复抢占。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-30\">三十 · 分离式预填/解码：把 prefill 的抖动从 decode 路径上摘出去</h3>\n<p>分离式（disaggregated）预填/解码把 prefill 与 decode 放到不同的 GPU 池，中间通过 KV 传输衔接。对本算法，分离的动机不是常规的“prefill 计算密集、decode 带宽密集”，而是把长回答 prefill 的时延抖动隔离在一个可独立扩容的池里，让 decode 侧的迭代节奏不被长样本拖慢。代价是 KV 传输：一条长回答的 KV 需要从 prefill 池搬到 decode 池，传输量随序列长度线性增长，走 NVLink 5 的域内传输与跨节点传输的成本差异显著，后者会把 prefill 池的扩容收益吃掉一部分。</p>\n<p>一个具体机制：prefill 池按桶接收长回答，完成切片后把 KV 分页句柄传给 decode 池，decode 池只负责逐 token 生成与 log-prob 累计。这样正负回答的两次前向可以分别落在两个池中并行推进，只要二者在同一策略版本窗口内完成即可。代价是版本同步：两个池必须共享同一份参数快照，更新时要么双池同时切换（带来一次全局停顿），要么让 decode 池延迟一个版本（破坏比值一致性）。工程判断是：更新频率低、批大的场景适合双池同步切换；更新频繁的场景应退回单池连续批处理，用桶内错峰而非物理分离来压抖动。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-31\">三十一 · 尾延迟：从 P50 到 P99 的三个具体手段</h3>\n<p>本算法的尾延迟有三个可辨识来源：长回答的 prefill、跨版本重算、以及批内正负长度不匹配导致的算力空转。对应的手段分别是长度分桶、原子单元优先级、以及按正负长度配对入批。第三个手段常被忽略：若正回答很短、负回答很长，二者在同一 iteration 内前向，短的那一侧很快算完而长的那一侧仍在跑，GPU 利用率由长侧决定；调度器应把长度相近的正负对配成一批，或允许短侧先完成并暂存 log-prob，等长侧完成后合并成对——后者需要暂存缓冲，代价是显存。</p>\n<p>尾延迟的量化抓手是分位数而非均值：设批内最慢样本的时延为 T_max，则 P99 批时延近似由 T_max 的分布决定，而 T_max 对批大小 B 的敏感度高于均值。因此把 B 从“时延允许的最大值”下调一档、换取更紧的 T_max 分布，往往比堆满批更能压 P99。这与实例相关分析的方向一致：批大小本就不是越大越好，方差与偏差的权衡已经给了一个上界，调度器不必再往上顶。材料未给出具体分位数目标与硬件档位，工程上应以留出偏好对胜率的方差监控作为旁证——若胜率抖动随批大小上升而放大，说明梯度估计方差已越过可接受区间，此时压批比压时延更优先。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-32\">三十二 · KV 复用与策略版本的耦合代价</h3>\n<p>每轮更新后策略变化，回答的 token 级对数概率必须重算，KV 缓存的复用受策略版本约束：同一版本内的重复前向可以命中 KV，跨版本则必须失效。这给调度器一个额外的维度——KV 命中率随更新频率下降。设更新周期为 N 个 iteration、单条回答的 KV 大小为 s，则版本内复用带来的带宽节省约为 (N−1)/N 的比例，N 越小节省越少。当更新频繁到 N 接近 1 时，KV 复用几乎无收益，此时连续批处理的价值退化为纯粹的打包效率，而 chunked prefill 的切片重读开销反而成为净负担。</p>\n<p>工程判断因此落在更新粒度上：把多个偏好对的梯度累积到一个更新步，等价于把 N 拉大，换取 KV 复用窗口；代价是梯度陈旧度上升，与实例相关界里“限制同一偏好对重复使用次数”的约束相互作用。一个具体例子：若一个更新步累积 4 个 micro-batch 的梯度，则这 4 个 micro-batch 共享同一策略版本，KV 可在其间复用，但每个偏好对在窗口内被看到一次而非四次，偏差可控；若改成每 micro-batch 更新一次，KV 全部失效且比值一致性窗口缩短，调度复杂度上升而吞吐下降。材料未给出具体累积步数，这一取舍应由胜率方差与 KV 命中率两个监控量共同决定，而不是由单一时延指标决定。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-33\">三十三 · 无奖励模型时的批调度边界：前向次数、KV 版本与长尾分桶</h3>\n<p>该方案在推理侧的独特代价来自“每步两次策略前向”的硬约束：正负回答各取一次 token 级对数概率，前向次数随批大小线性增长，且策略更新后旧版本的对数概率立即失效。设批内第 i 条样本的正、负回答长度分别为 L⁺ᵢ、L⁻ᵢ，单批前向 token 量为 <span class=\"formula\">$$T_{\\text{batch}}=\\sum_{i=1}^{B}(L_i^{+}+L_i^{-})$$</span>，则单批延迟近似由最长样本决定而非均值决定，这正是连续批处理在此处失效的边界——连续批处理靠迭代级调度填满空位，但本方案要求同一条偏好对的正负回答在同一策略版本下成对计算，跨迭代拼接会引入版本不一致的梯度估计偏差。因此可用的调度粒度是“偏好对级”而非“请求级”：一个偏好对作为一个不可拆分的调度单元，批内按对填充，空位只能由同版本的其他偏好对补齐。当批大小按实例相关界设定且需限制同一偏好对重复使用次数时，可补位的候选池被进一步压缩，批利用率下降，吞吐对批大小的敏感度高于常规生成服务。</p>\n<p>KV 复用的收益在此被策略版本严格约束。每轮更新后 π_θ 变化，缓存中的 KV 只对旧版本有效，跨版本复用等价于用陈旧策略估计当前对数概率，直接污染 sigmoid 偏好概率与梯度权重。可行的折中是版本内复用：同一策略版本下的多轮采样共享前缀 KV，把正负回答的公共提示段（prompt）只前向一次，差异部分各自计算；设提示长度为 L_p，则节省比例为 <span class=\"formula\">$$\\eta_{\\text{kv}}=\\frac{L_p}{L_p+\\bar L^{+}+\\bar L^{-}}$$</span>，其中横杠表示批内均值。提示越长、回答越短，复用收益越大；反之在长回答、短提示的偏好数据上收益趋近于零，此时 KV 策略对吞吐几乎没有贡献，系统代价回落到纯前向算力。这也是该方案与分离式预填/解码的接缝处：预填阶段可对提示做一次共享前向，解码阶段则必须按版本隔离，不能把解码 KV 跨版本池化。</p>\n<p>尾延迟的压制手段只剩长度分桶与优先级两件。长尾样本拉高单批延迟的机理是明确的：单批延迟由批内最长正负回答对决定，一条超长样本会把整批的完成时间拖到其长度量级，而其余短样本的算力在等待中空转。按长度分桶调度可把长尾隔离到独立批次，代价是短桶批次变浅、批利用率下降，长桶批次变深、单批延迟上升，形成吞吐与尾延迟的显式取舍。优先级机制在此需谨慎：若给短样本高优先级以压 P99，长样本会被持续饥饿，而长样本恰是梯度估计方差的主要来源，饥饿会破坏实例相关界所依赖的数据覆盖条件。工程判断是：分桶阈值应按回答长度分布的分位点设定而非固定值，长桶批次允许更小的批大小以控制单批延迟上界，同时对同一偏好对的重复使用计数做全局配额，避免某条长样本因反复补位而被过度采样。该方案未涉及量化采样稳定性，NVFP4/FP8 下 sigmoid 输入的对数概率差在小值区间的数值行为需另行验证，不能把常规生成服务的量化结论直接外推。</p>\n<table class=\"mini\"><thead><tr><th>调度决策</th><th>收益</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>偏好对级批填充</td><td>梯度估计版本一致</td><td>候选池被重复使用配额压缩</td><td>批利用率下降，吞吐对批大小敏感</td></tr><tr><td>版本内前缀 KV 复用</td><td>提示段只前向一次</td><td>短提示长回答分布</td><td>收益趋零，回落到纯前向算力</td></tr><tr><td>长度分桶 + 长桶小批</td><td>压 P99 尾延迟</td><td>分桶阈值固定、长样本饥饿</td><td>短桶变浅，批吞吐下降</td></tr></tbody></table>\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-34\">三十四 · 并行切分：四种轴与偏好优化的前向结构</h3>\n<p>在 Blackwell 上把免奖励推断的偏好优化跑成服务，第一步不是选框架，而是决定把策略模型切到哪几条轴上。张量并行（TP）切分单层内的权重矩阵，每层做一次 All-Reduce 把部分和拼回完整激活；专家并行（EP）把 MoE 的专家分到不同 rank，前向路径上必须做 All-to-All 把 token 路由到所属专家再收回；流水并行（PP）按层切段，段间只传激活，边界处是点对点而非集合通信；数据并行（DP）复制整模型、切分偏好样本批次，梯度侧才需要规约。这四种轴的通信语义完全不同：TP 与 EP 是每层每 token 都要付的通信税，PP 是每微批一次的边界传输，DP 在纯推理前向里几乎不通信。</p>\n<p>偏好优化的前向结构决定了这笔税怎么算。给定一条偏好样本 $(x,y^+,y^-)$，算法要对正负回答各做一次策略前向取对数概率，两次前向共享同一提示 $x$ 的 KV 前缀。若把 $y^+$ 与 $y^-$ 拼成一条序列做变长批处理，TP 组内的 All-Reduce 次数按层数乘以序列块数计；若分两条请求下发，前缀 KV 被复制两份，显存与带宽同时翻倍。设层数 $L$、每层 All-Reduce 传输量 $S$（激活字节数）、TP 度 $T$，单次前向的 TP 通信量为：</p>\n<div class=\"formula\">$$V_{\\mathrm{TP}} \\approx 2L\\cdot\\frac{T-1}{T}\\cdot S$$</div>\n<p>系数 2 来自 All-Reduce 的 reduce-scatter 与 all-gather 两段。工程含义直接：TP 度从 2 提到 4 时单次传输量上升但单卡权重下降，若模型能塞进更小 TP 度，就应优先降 TP 度换通信；反之当单卡显存装不下 KV 与权重时才升 TP。对偏好优化这种每步两次前向、且每轮更新后要重算 token 级对数概率的负载，TP 度是延迟的第一主导项，而 DP 度只影响批吞吐。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-35\">三十五 · NVLink 5 与 NVSwitch：域内带宽与集合通信的代价</h3>\n<p>GB200/GB300 NVL72 机柜内是 NVLink 5 域，单 GPU 对外聚合带宽远高于 PCIe，NVSwitch 让机柜内任意两 GPU 之间是全互联而非胖树收敛。这意味着 TP 与 EP 的集合通信可以落在 NVLink 域内完成，All-Reduce 的环或树算法在 72 卡规模内不必经过 InfiniBand。判断通信是否成为瓶颈，先看“计算-通信比”：单层矩阵乘的浮点工作量与 All-Reduce 字节数之比，再除以该层的算术强度与链路带宽。</p>\n<p>以 BF16 激活、隐藏维 $H$、序列块 $B\\cdot s$ 为例，一层注意力的 QKV 投影计算量约为 $O(BsH^2)$，而 All-Reduce 传输量为 $O(BsH)$ 字节量级，比值随 $H$ 增大而改善。这就是为什么 TP 在大隐藏维模型上划算、在小模型上纯属浪费：当 $H$ 不够大时，All-Reduce 的固定延迟（kernel launch 与同步开销）压过计算，TP 组内每层都在等最慢的 rank。NVLink 5 抬高了带宽上限，但没有消除同步点——TP 组内任一 rank 的负载不均（例如变长序列里某 rank 分到的 token 更多）都会让整组空转。</p>\n<p>具体例子：一条偏好样本的正回答长度远大于负回答，若两条请求被分到同一 TP 组的相邻 rank 上做批处理，变长批的 padding 与负载偏斜会让 All-Reduce 的等待时间由最长序列决定。代价体现在单批延迟的尾部分布上，而不是平均吞吐。工程上应把正负回答按长度分桶后再组批，让 TP 组内各 rank 的 token 数接近，否则 NVLink 带宽再宽也救不了同步等待。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-36\">三十六 · All-to-All 与 EP：MoE 策略模型的隐藏税</h3>\n<p>若策略模型是 MoE，EP 的 All-to-All 是比 TP 更尖锐的瓶颈。每个 token 经门控选出 top-k 专家，token 需被发送到持有该专家的 rank，专家算完再把结果发回原 rank。All-to-All 的传输量与路由分布直接相关：路由越不均衡（少数专家吃掉大部分 token），热点 rank 的收发队列越长，整组等待越久。设每 token 路由到 $k$ 个专家、每 token 激活字节 $a$、批内 token 数 $N$、EP 度 $E$，一次前向的 All-to-All 量级为：</p>\n<div class=\"formula\">$$V_{\\mathrm{EP}} \\approx 2kNa\\cdot\\frac{E-1}{E}$$</div>\n<p>与 TP 不同，EP 的通信量随批内 token 数线性增长，因此大 batch 会放大 All-to-All 开销。对偏好优化而言，每步要对正负回答各做一次前向，批大小按实例相关界设定、需限制同一偏好对重复使用次数，这意味着批不能无限放大来摊薄通信——批大了 EP 通信线性涨，批小了 TP 同步开销占比高，存在一个由路由均衡度与链路带宽共同决定的甜点区。</p>\n<p>推理系统代价：All-to-All 的尾延迟通常由最热专家决定，容量规划要按专家负载的峰值而非均值算带宽。若策略模型是稠密模型，EP 轴不存在，通信只剩 TP 与 PP；若模型走 MoE，则必须在路由层做容量因子与 token 丢弃策略的权衡——丢弃会改变策略分布，进而影响偏好概率估计的偏差，这与算法侧“限制同一偏好对重复使用次数以控制估计偏差”是同一类问题的两个面。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-37\">三十七 · PP 边界与 DP 的错位：谁在等谁</h3>\n<p>流水并行把层切成段，段间只传激活张量，通信量远小于 TP 的每层 All-Reduce，但代价是流水气泡。纯推理场景下 PP 的收益来自“单卡装不下整模型”而非带宽节省；一旦段数增多，微批要填满流水线才有吞吐，而偏好优化的单批只有正负两条回答，微批数不足以填满深流水，气泡占比高。判断 PP 是否值得，看微批数 $m$ 与段数 $P$：填充-排空开销约为 $(P-1)/m$ 个微批时间，$m$ 不够大时 PP 纯属增延迟。</p>\n<p>DP 在纯前向推理里几乎不通信，但在“每轮更新后重算对数概率”的流程里，DP 副本之间的策略权重必须一致，否则同一偏好对在不同副本上算出不同的对数概率，梯度估计的方差被副本差异污染。权重同步因此成为 DP 的隐性成本：同步频率与策略更新频率绑定，更新越频繁，同步开销占比越高。这与 KV 复用受策略版本约束是同一约束的两端——策略一变，缓存的对数概率与 KV 都失效。</p>\n<p>具体例子：把偏好数据按 DP 度切分，每个副本处理不同偏好对，前向各自独立、无集合通信；但每步结束要更新策略，若各副本独立更新则权重发散，必须做一次跨副本规约或参数广播。这次广播的量级是整模型参数量，远大于单批前向的 TP 通信量，因此 DP 度越高、更新越频繁，权重同步越可能成为实际瓶颈。工程判断：偏好优化这类每步都要前向取对数概率的负载，应优先用 TP 装下模型、用 DP 提吞吐，并把更新频率与同步成本一起纳入调度设计。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-38\">三十八 · NIXL 传输与分离式部署：跨节点的那一段</h3>\n<p>当模型大到单机柜装不下，或采用分离式预填/解码时，通信跨出 NVLink 域进入 InfiniBand 或以太网，NIXL 这类传输库负责在节点间搬运 KV 与激活。NIXL 的价值在于把传输抽象成点对点内存操作，绕开集合通信的全局同步，适合预填节点向解码节点单向灌 KV 的场景。对免奖励推断的偏好优化，分离式部署的动机是：前向取对数概率是纯计算密集，可放在预填侧批量做；而偏好样本的采样与组批在调度侧完成，两侧通过 NIXL 传 KV 而非传整段激活。</p>\n<p>跨节点传输的瓶颈判据是“每 token 每层的 KV 字节数 × 层数 × token 数”对比链路带宽。KV 传输量与序列长度线性相关，长尾样本在这一段被二次放大：长回答的 KV 更大，跨节点搬运时间更长，且这段延迟不与其他请求的 TP 计算重叠。系统代价体现在 P99 延迟上，容量规划要按长尾序列的 KV 体积算跨节点带宽，而不是按均值。若跨节点带宽不足，分离式部署的收益会被传输延迟吃掉，此时宁可回到单机柜内用 TP+PP 装下模型。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-39\">三十九 · 通信何时成为瓶颈：三个判据与一个工程落点</h3>\n<p>判据一，计算-通信比。单层计算时间 $t_c$ 与集合通信时间 $t_m$ 之比小于约 1 时，通信主导；$t_m$ 由传输量与有效带宽决定，有效带宽在 NVLink 域内高、跨节点低。判据二，同步点数量。TP 每层一个 All-Reduce、EP 每层一个 All-to-All，层数越多同步点越多，固定延迟累积；PP 只有段边界同步，但气泡随段数增长。判据三，负载偏斜。变长批与 MoE 路由不均衡都会让集合通信的等待时间由最慢 rank 决定，此时平均带宽指标失去意义，要看尾部。</p>\n<p>把三条判据落到偏好优化的具体流程：每步正负回答各一次前向，前向次数随批大小线性增长，长尾样本拉高单批延迟；批大小受实例相关界约束不能无限放大，因此不能用“大 batch 摊薄通信”的常规手段。可行的工程落点是长度分桶加前缀 KV 共享：正负回答共享提示 $x$ 的前缀 KV，把两条请求合成一条变长批，减少一次前缀计算与一次 TP 组内的重复 All-Reduce；同时按长度分桶让 TP 组内各 rank 的 token 数接近，压低同步等待的尾部。</p>\n<p>最终判断落在通信轴的选择上：模型能装进单机柜 NVLink 域时，优先低 TP 度加 DP 提吞吐，避免跨节点；必须跨节点时，用 NIXL 做点对点 KV 搬运而非全局集合通信，并按长尾 KV 体积算带宽；MoE 策略模型要把 All-to-All 的路由均衡度当作一等指标，路由偏斜会直接转化为偏好概率估计的批延迟抖动。这些代价都不改变算法本身的无模型梯度形式，但决定了它在 Blackwell 上能否稳定跑进 SLO。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-40\">四十 · 偏好梯度回传时的通信边界：为何该方案几乎不触碰 TP/EP 的 All-to-All</h3>\n<p>该算法的并行需求与常规 RLHF 有本质差异：它不维护奖励模型与价值网络，反向传播只沿策略参数一条路径进行，因此不存在“奖励模型前向 + 策略反向”两套张量并行组之间的梯度汇聚。真正决定通信形态的是每步对正负回答各做一次策略前向取对数概率。若策略以张量并行（TP）切分，则每次前向在每层注意力和 MLP 后各需一次 All-Reduce 汇聚部分和；若以专家并行（EP）部署 MoE，则每层需一次 All-to-All 做 token 路由。设单次前向含 $L$ 层、每层一次集合通信、单次通信量 $B$ 字节，则一步的通信量为</p>\n<div class=\"formula\">$$V_{\\text{comm}} \\approx 2 \\cdot L \\cdot B \\cdot \\left(1 + \\frac{N-1}{N}\\right)$$</div>\n<p>其中因子 2 来自正负回答两次前向，$N$ 为并行度，$(N-1)/N$ 反映 All-Reduce 的环状带宽利用率。关键判断是：由于反向只更新策略、且对数概率之差经 sigmoid 加权后是一个标量系数，梯度估计器本身不引入跨设备的额外归约——这与 PPO 中优势函数需在 rollout 与训练之间同步形成对比。代价落在延迟侧：长尾样本使单批内最慢序列决定前向完成时刻，两次前向串行叠加，All-Reduce 的等待被放大；而在 NVLink 5 域内（GB200 NVL72 单机架 72 卡全互联、NVSwitch 提供无阻塞交换），TP 组内 All-Reduce 可落在高带宽域内，跨机架才退化为 InfiniBand 与 NIXL 传输，此时通信开始成为瓶颈。</p>\n<p>失效条件有三类。其一，若把偏好对缓存跨更新轮复用，策略版本变化使旧 token 对数概率失效，KV 复用收益随更新频率下降，重算前向又回到通信主导；其二，EP 场景下 All-to-All 的尾延迟对不均衡路由极敏感，长尾回答的 token 分布偏移会加剧热点专家，此时即便 NVLink 5 带宽充裕，交换排队仍抬高单批延迟；其三，若为省显存把策略切到 PP，则流水线气泡与正负两次前向的微批交错会引入额外空转，PP 的跨 stage 激活传输在 NIXL 上表现为点对点搬运，其代价随 stage 数线性上升。工程判断是：该算法应优先采用 TP 组内闭合、避免跨机架 All-to-All 的拓扑，把通信预算留给策略前向而非梯度归约；在分布偏移使界失效的场景，通信优化无法补偿样本效率的损失。</p>\n<table class=\"mini\"><thead><tr><th>并行维度</th><th>本方案通信形态</th><th>瓶颈触发点</th></tr></thead><tbody><tr><td>TP</td><td>每层 All-Reduce，两次前向叠加</td><td>跨机架退化、长尾拖尾</td></tr><tr><td>EP</td><td>每层 All-to-All 路由</td><td>专家热点、路由不均衡</td></tr><tr><td>PP</td><td>stage 间激活点对点</td><td>气泡与微批交错空转</td></tr><tr><td>DP</td><td>仅参数梯度 All-Reduce</td><td>偏好对重复使用致偏差</td></tr></tbody></table>\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-41\">四十一 · 精度塌陷：从“界失效”到可观测信号</h3>\n<p>这篇论文的保证是实例相关的：遗憾界与样本复杂度依赖偏好模型假设与数据覆盖条件。工程上所谓“精度塌陷”，不是指 FP8 溢出，而是指偏好估计器输出的相对优势分布退化——sigmoid 后的偏好概率长期贴近 0 或 1，梯度加权项失去分辨力。机制上，梯度估计器为 <span>σ(log πθ(y+|x) − log πθ(y−|x))</span> 加权正回答对数概率梯度；当策略对正负回答的似然差被拉到极端区间，σ 饱和，更新方向几乎只由正回答自身梯度决定，偏好对的比较信息被丢弃。诊断信号应直接取自这个量：按批统计偏好概率的均值与分位数、饱和比例（p&lt;0.05 或 p&gt;0.95 的占比）、以及梯度估计方差。代价上，饱和意味着有效样本量下降，达到同等留出胜率需要更多轮次，而每轮每样本两次策略前向的开销不变，等于用吞吐换精度却换不到。具体例子：长度分桶后某一桶内正负回答长度差异系统性偏大，对数概率差被长度项主导，该桶饱和比例显著高于全局，此时应回滚到上一版策略并复查该桶的采样配比，而不是调步长。</p>\n<div class=\"formula\">$$\\hat{p}=\\sigma\\!\\left(\\log\\pi_\\theta(y^+|x)-\\log\\pi_\\theta(y^-|x)\\right),\\quad \\text{sat}=\\frac{1}{B}\\sum_{i=1}^{B}\\mathbb{1}[\\hat{p}_i&lt;0.05 \\lor \\hat{p}_i&gt;0.95]$$</div>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-42\">四十二 · OOM 与显存账：省掉奖励模型不等于省掉峰值</h3>\n<p>部署侧确实省去了奖励模型与验证器推理链路，显存占用与服务调度复杂度下降。但峰值显存的主导项转移了：每步需对正回答与负回答各做一次策略前向取 token 级对数概率，激活与 KV 随批大小线性增长，且反向只更新策略参数、不经过奖励模型，梯度检查点策略必须重排。OOM 的典型触发不是稳态而是批抖动叠加长尾：一个超长偏好对进入批内，其 KV 与激活把峰值顶穿。定位方法是把显存峰值按“稳态/批峰值/单样本峰值”三层拆开记录，并标注当批的最大序列长度与桶归属；若峰值与最大长度强相关而非与批大小相关，说明问题在分桶阈值而非批上限。代价判断：降低批大小能压峰值但直接抬高每 token 摊销的调度与权重读取开销，吞吐下降；正确做法是长度分桶加批内长度方差上限，把长尾样本隔离到独立小批。回滚路径应是配置级——回退分桶阈值与批上限，而非回退策略权重，因为 OOM 是调度问题不是数值问题。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-43\">四十三 · 批抖动与尾延迟：两次前向的乘性放大</h3>\n<p>该算法每步对正负回答各一次前向，单批延迟近似为两次前向的串行叠加，前向次数随批大小线性增长。批抖动的来源是偏好对长度分布的重尾：同一批内若混入长回答，解码步数与 KV 占用同时抬升，尾延迟被乘性放大——不是加法，因为正负两次前向都要走完最长序列的步数。稳定吞吐的手段是长度分桶调度，把长度相近的偏好对编入同批，使批内最大长度接近均值；材料未给出分桶阈值，工程上应以“批内长度方差/均值”作为监控量，超过设定比例即触发重分桶。尾延迟监控不能只看均值，要记录 P99 与“慢批占比”，并把慢批关联到其桶与最大长度，形成可归因的尾延迟账本。具体例子：某轮 P99 突然抬升而均值平稳，账本显示慢批全部落在最长桶且该桶批大小未变，说明是采样配比漂移把长样本挤进了同一批，处理是调整采样权重而非缩小批。代价上，分桶会降低批内样本多样性、轻微增加批数，属于用少量吞吐换尾延迟确定性。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-44\">四十四 · 静默降级：缓存复用与策略版本错配</h3>\n<p>最危险的失败模式没有报错。每轮更新后策略变化，token 级对数概率必须重算；若为省算力而复用上一版策略缓存的 KV 或对数概率，估计器用的就是旧策略的似然，梯度方向与当前策略不一致，训练仍在跑、损失仍在降，但留出偏好对胜率停滞甚至缓降——这就是静默降级。机制上，缓存复用收益随更新频率下降：更新越频繁，缓存命中带来的节省越少，而错配风险越大。诊断靠版本戳：每个缓存条目携带策略版本号，批内若出现版本不一致即计数并告警；同时监控“缓存命中率”与“留出胜率”的联合走势，命中率上升而胜率不升即为降级信号。代价是缓存失效带来的重算开销，等于把省下的前向又还回去；工程判断是宁可降低缓存复用深度，也不允许跨版本复用对数概率。回滚动作明确：清空缓存、回退到上一版策略权重、重跑留出评估，确认胜率恢复后再恢复调度参数。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-45\">四十五 · 监控面与回滚判据</h3>\n<p>监控面按三层组织：数值层看偏好概率分布与饱和比例、梯度估计方差；系统层看显存三层峰值、批内长度方差、P99 与慢批占比、缓存版本一致性；效果层看留出偏好对胜率。三者需同时间轴对齐，否则无法区分“数值退化”与“调度退化”。回滚判据应是组合条件而非单指标：饱和比例越限且胜率不升，回滚策略权重；显存峰值越限且与最大长度强相关，回滚分桶配置；缓存版本不一致计数非零，立即清缓存并回滚权重。材料未给出阈值，阈值须由自身基线分布定，且每次变更配置后重设基线。该工作未涉及 NVFP4/FP8 量化下的采样稳定性，量化部署的数值退化需另行验证，不能把本文的界当作量化稳定性的依据。最后落在工程判断上：这套流程的失败大多不是算法错，而是调度与缓存把“当前策略的似然”悄悄换成了别的版本——版本戳与分桶账本比任何理论常数都更能挡住静默降级。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-46\">四十六 · 免奖励推断流水线的失效边界：从精度塌陷到静默降级的诊断与回滚</h3>\n\n<p>这套方案在推理侧的诱人之处是砍掉奖励模型与验证器链路，但它把全部数值风险集中到了策略前向本身：梯度权重来自 <span class=\"formula\">$$\\sigma\\!\\left(\\log\\frac{\\pi_\\theta(y^+|x)}{\\pi_\\theta(y^-|x)}\\right)$$</span> 这一个标量，正负对数概率之差一旦被数值误差污染，权重就会系统性偏移，而链路里没有任何奖励模型可以作为交叉校验的第二信号源。这正是它区别于常规 RLHF 部署的第一条失效边界：<strong>精度塌陷是静默的</strong>。在 Blackwell 上把策略前向切到 FP8 或 NVFP4 做吞吐优化时，token 级对数概率的累加误差会直接进入 sigmoid 自变量；当正负回答长度差异大、对数概率绝对值达到数十量级时，低精度累加可使差值偏差跨过 sigmoid 的饱和区，权重被压到 0 或 1，梯度估计器退化为对单一回答的硬加权。材料明确未给出量化下的采样稳定性数据，因此工程上必须把「策略前向精度」与「梯度权重分布」绑定监控：以固定小批偏好对为探针，周期性用高精度参考实现重算权重，比较其分布漂移，而不是只看 loss 曲线——loss 在权重饱和时反而可能显得平滑。</p>\n\n<p>第二条边界是<strong>批抖动与尾延迟的结构性放大</strong>。每步需对正负回答各做一次策略前向，前向次数随批大小线性增长，而偏好对的正负回答长度分布不受控：一条长尾样本的正向与负向都可能是长序列，单批延迟由该批最长序列决定，于是批内长度方差直接转化为 P99 抖动。这与常规推理不同——常规服务可以按 token 计费式地流式返回，而这里必须等两条回答的 token 级对数概率全部就绪才能算出权重，属于典型的「全批同步屏障」。缓解手段是采样阶段按长度分桶、桶内再按正负长度之和排序组批，把批内极差压到可控范围；代价是分桶会降低批填充率，短桶的显存与算力利用率下降，吞吐与尾延迟之间形成显式兑换。KV 复用在这里同样受限：策略每轮更新后 token 级对数概率必须重算，缓存只在同一策略版本内有效，更新频率越高、复用收益越低，若为省显存而跨版本复用 KV，则会引入与当前策略不一致的概率，等价于给梯度权重注入系统偏差。</p>\n\n<p>第三条是<strong>理论界失效后的静默降级</strong>。实例相关样本复杂度与遗憾界依赖偏好模型假设与数据覆盖条件，分布偏移或长尾样本可能使界失效，而材料未给出具体常数与阈值。工程表现是：留出偏好对胜率停止上升甚至缓慢下滑，但训练 loss 与梯度范数仍在正常区间，监控面板上没有任何红色告警——这就是静默降级。诊断应把「同一偏好对重复使用次数」作为一等指标：重复使用越多，估计偏差越难被新样本稀释，胜率与梯度的背离越明显。定位路径是先冻结策略、用留出集重算权重分布，再比对训练期权重分布的分位数漂移；若漂移集中在高分位，说明长尾样本主导了更新。回滚策略应绑定策略版本而非全局 checkpoint：由于缓存与对数概率都带版本标签，回滚到上一稳定版本时须同步丢弃该版本之后的 KV 缓存与概率缓存，否则会出现「旧权重配新概率」的错配，比不回滚更危险。表内给出四类信号与对应动作的对应关系，作为值班手册的最小集。</p>\n\n<table class=\"mini\"><thead><tr><th>信号</th><th>观测位置</th><th>判读</th><th>动作</th></tr></thead><tbody><tr><td>权重分布高分位漂移</td><td>探针批重算 vs 训练期</td><td>精度塌陷或长尾主导</td><td>切回高精度前向，缩批</td></tr><tr><td>P99 与 P50 延迟比抬升</td><td>批调度器</td><td>长度方差放大</td><td>收紧分桶阈值，降填充率</td></tr><tr><td>胜率平而梯度范数正常</td><td>留出偏好对</td><td>分布偏移下界失效</td><td>限重复使用次数，重采样</td></tr><tr><td>KV 命中率虚高</td><td>缓存层</td><td>跨版本复用错配</td><td>按版本失效缓存后回滚</td></tr></tbody></table>\n\n<p>还有一条容易被忽略的代价：省掉奖励模型确实降低了显存占用与服务调度复杂度，但策略前向开销上升，且这部分开销不可被奖励链路的并行所摊薄——奖励模型本可与策略前向流水并行，如今两次前向串行在同一策略上，单步关键路径变长。因此在容量规划上，不能把「去掉奖励模型」直接折算为吞吐增益；正确做法是把每步的正负两次前向视为不可压缩的关键路径，用分桶与批内排序去压缩其方差，而不是压缩其均值。至于 NVFP4/FP8 下的采样稳定性，材料未给出任何量化方案与数值实验，任何外推都不成立，落地前必须自建探针批做精度回归，把权重分布漂移纳入发布门禁。</p>\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-47\">四十七 · 为什么这篇论文的“基准”必须先被拆成两套口径</h3>\n<p>这篇论文的工程特殊性在于，它同时落在两个测量体系里：算法侧要报告的是样本复杂度与遗憾界，推理侧要报告的是 TTFT、TPOT、吞吐、显存与功耗。二者不是同一把尺子。算法侧的“快”指达到给定胜率所需的偏好对数量少，推理侧的“快”指单位时间内完成的 token 数多。把论文的实例相关界直接换算成“比奖励模型方案省多少毫秒”是错误外推，因为材料没有给出任何硬件档位、批大小数值与吞吐数字。正确读法是：先确认一个数字属于哪套口径，再判断它是否可与其他条目横向比较。</p>\n<p>本部分要建立的判断规则是：凡涉及“省去奖励模型”的收益，只能定性归入显存占用与服务调度复杂度两类；凡涉及“每步正负回答各一次前向”的代价，必须归入策略前向次数与单批延迟两类。任何跨过这条界线的数字，都不可比。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-48\">四十八 · 硬件档位与部署形态：材料给出的边界在哪</h3>\n<p>论文未涉及 B200/B300、GB200/GB300 NVL72 的具体配置，未给出并行拓扑、NVFP4/FP8 量化方案与 KV 策略。这意味着在 Blackwell 专卷的语境下，这篇工作只能作为“算法结构对推理链路的影响”来读，不能作为“Blackwell 上的实测性能”来读。工程读者需要把它的结论放进一个假想的部署形态里检验：推理侧只需策略模型前向生成候选回答，奖励信号来自离线偏好对而非在线奖励模型打分，因此部署上省去奖励模型服务与验证器推理链路。</p>\n<p>省去的是什么，要算清楚。常规 RLHF 部署中，奖励模型是一份独立的权重，占一份显存；验证器链路是一次额外的前向，占一份算力与一份调度槽位。这篇论文把这两项从部署图里删掉，收益体现在显存占用下降与服务调度复杂度下降，而不是体现在单次前向的延迟下降。反过来，代价出现在训练与采样侧：每步需对正负回答各做一次策略前向以取得对数概率，前向次数随批大小线性增长。设批大小为 $B$，每步策略前向次数为</p>\n<div class=\"formula\">$$N_{\\text{fwd}} = 2B$$</div>\n<p>这个系数 2 是本论文所有延迟讨论的起点。它不随硬件档位变化，只随批大小与回答长度变化。因此在没有硬件数据的前提下，唯一能做的定量推算是：批大小翻倍，单步前向开销翻倍；回答长度进入长尾，单批延迟被最长样本拉高。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-49\">四十九 · batch、并发与指标：四个指标各自的归属</h3>\n<p>TTFT 在这篇论文的语境下不由算法决定，而由策略模型的首 token 前向与调度排队决定；论文没有给出并发与 SLO 数据，因此 TTFT 只能作为“部署侧另行测量”的指标，不能从论文结论推出。TPOT 同理，取决于解码阶段的 KV 复用与批内 token 交织，材料未给出 KV 策略，只知每轮需重算或缓存回答的 token 级对数概率。吞吐则要拆成两个方向：训练吞吐受 $2B$ 次前向约束，推理吞吐受策略模型自身解码效率约束，二者不可混谈。</p>\n<p>显存是这篇论文唯一能给出结构性结论的指标。省去奖励模型参数与验证器推理链路，直接减少一份权重占用与一份激活占用；但策略前向次数上升，激活峰值随批大小线性增长。功耗在材料中完全缺位，不能外推。把四个指标排成一张归属表，读数字时先查表：</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>归属口径</th><th>论文能否给出</th><th>可比性判断</th></tr></thead><tbody><tr><td>TTFT</td><td>推理侧，调度与首 token 前向</td><td>否，材料未给并发与 SLO</td><td>不可与实测条目横向比</td></tr><tr><td>TPOT</td><td>推理侧，解码与 KV 复用</td><td>否，材料未给 KV 策略</td><td>不可比</td></tr><tr><td>吞吐</td><td>训练侧 $2B$ 前向 / 推理侧解码</td><td>仅能定性给出前向次数关系</td><td>只可同口径内部比较</td></tr><tr><td>显存</td><td>省奖励模型权重与验证器链路</td><td>可定性，无具体数值</td><td>结构性可比，数值不可比</td></tr><tr><td>功耗</td><td>—</td><td>否</td><td>不可比</td></tr></tbody></table>\n<p>具体例子：若某部署把批大小从 $B$ 提到 $2B$，按 $N_{\\text{fwd}}=2B$ 的关系，单步前向次数翻倍，激活峰值上升，而省去奖励模型带来的显存收益是固定的一份权重，不随批大小变化。因此在显存紧张时放大批大小，收益会被激活增长吃掉；在小批量下，省奖励模型的显存收益占比更高。这是本论文唯一能给出的、不依赖硬件的工程判断。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-50\">五十 · 数字怎么读：三类不可比的提升</h3>\n<p>第一类不可比是“省去奖励模型”与“降低延迟”之间的偷换。论文的收益是部署链路简化与显存占用下降，不是单次请求延迟下降；每步仍需正负回答各一次前向，长尾样本会拉高单批延迟。任何把“无奖励模型”读成“更快出 token”的说法都越过了材料边界。</p>\n<p>第二类不可比是理论界与实测吞吐之间的偷换。论文以实例相关分析给出样本复杂度与遗憾界，强调无需奖励推断即可获得可证明保证；材料未给出具体胜率、吞吐或显存数字。遗憾界是偏好对数量维度上的量，吞吐是 token 每秒维度上的量，两者之间没有材料给出的换算系数。</p>\n<p>第三类不可比是量化精度下的采样稳定性。该工作未涉及 NVFP4/FP8 量化下的采样稳定性，材料未给出量化方案与数值精度实验。在 Blackwell 上部署时，策略前向取对数概率这一步对数值精度敏感：对数概率之差经 sigmoid 变换得到偏好概率估计，若 logits 在低精度下被截断，sigmoid 输入端的差值会被放大或压平。工程落地需另行验证，不能引用论文结论。用伪代码表达这条读取纪律：</p>\n<ul><li>读到一个“提升”，先问它属于样本复杂度口径还是推理吞吐口径；</li><li>若属于前者，只能与同用偏好对数量计量的工作比较；</li><li>若属于后者，必须确认硬件档位、批大小、量化方案三者齐备，否则标记为不可比；</li><li>凡材料未给出的指标（TTFT、TPOT、功耗、并发），一律不回填数字。</li></ul>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-51\">五十一 · 缓存与 KV 复用的口径陷阱</h3>\n<p>论文指出每轮更新后策略变化，需重新计算回答的 token 级对数概率，缓存复用受策略版本约束，KV 复用收益随更新频率下降。这是一条可以直接进入基准设计的机制：缓存的有效期等于策略版本的有效期。设更新周期为 $T$，缓存命中率为 $h$，则有效前向次数近似为</p>\n<div class=\"formula\">$$N_{\\text{eff}} \\approx 2B\\,(1-h),\\quad h = h(T)$$</div>\n<p>更新越频繁，$T$ 越小，$h$ 越低，$N_{\\text{eff}}$ 越接近 $2B$。因此报告吞吐时必须同时报告更新频率，否则两个吞吐数字不可比：一个每百步更新一次的系统与一个每步更新的系统，缓存命中率不同，前向开销不同。具体例子：同一批偏好对在策略更新后被重复使用时，旧缓存的对数概率已不对应当前策略，若继续复用会引入估计偏差；论文要求控制同一偏好对重复使用的次数以限制估计偏差，这条约束与缓存复用直接冲突，工程上必须在“复用省前向”与“偏差可控”之间取一个更新周期。</p>\n<p>KV 复用的收益还受长度分桶影响。长尾样本拉高单批延迟，因每步需正负回答各一次前向；建议按长度分桶调度以稳定吞吐，材料未给出分桶阈值。分桶阈值本身就是一个基准参数：阈值定得粗，长尾样本混入短批，单批延迟被拉高；阈值定得细，批内样本数下降，前向利用率下降。这条权衡在材料中没有数值，只能作为部署时的调参项记录。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-52\">五十二 · 把这篇论文放进可比矩阵的位置</h3>\n<p>在 Blackwell 推理的基准矩阵里，这篇论文占据的是“算法结构改变部署图”这一格，而不是“算子或精度带来吞吐提升”那一格。它的可比对象是同样讨论奖励模型是否必要的偏好优化工作，比较维度应是偏好对数量、是否维护价值网络、是否需在线奖励打分；不可比对象是报告 TTFT/TPOT 的部署实测工作。工程判断落在两点：其一，若部署侧显存与服务调度是瓶颈，省去奖励模型与验证器链路是结构性收益，与硬件档位无关；其二，若吞吐是瓶颈，则 $2B$ 次前向与策略版本约束下的缓存失效是主要代价，必须用长度分桶与更新周期调参来对冲，且这些调参结果不能引用论文数字，只能自测。</p>\n<p>最后落到一个具体机制上：偏好概率由正负回答对数概率之差经 sigmoid 得到，梯度以该概率加权正回答对数概率。这个式子里没有任何奖励模型参数，也没有独立价值网络，因此部署图里少两个服务；但式子里有两次策略前向，因此采样侧的批调度必须按 $2B$ 与长度分桶设计。基准报告应当把这两件事分开写：显存与调度复杂度按结构性收益记，前向开销与单批延迟按自测数据记，中间不插入任何跨口径的换算。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-53\">五十三 · 免奖励推断方案的口径边界：哪些数字能比，哪些不能</h3>\n<p>这套方法在部署侧省掉的是奖励模型与验证器链路，代价则全部压到策略前向上：每步对正回答与负回答各做一次前向取对数概率，前向次数随批大小线性增长。因此读它的性能数字时，第一件事是把“奖励打分前向”与“策略前向”分开记账——前者被消除，后者被翻倍。设批大小为 <span class=\"formula\">$$B$$</span>、单条回答平均 token 数为 <span class=\"formula\">$$L$$</span>，单步前向 token 量为 <span class=\"formula\">$$2BL$$</span>；长尾样本把 <span class=\"formula\">$$L$$</span> 的方差直接注入单批延迟，这是与常规 RLHF 流水线不同的延迟结构。分桶调度能压住这个方差，但分桶阈值材料未给出，只能按长度分布自行标定。</p>\n<p>指标口径上，TTFT 与 TPOT 描述的是生成侧，而本方案每轮更新后策略参数变化，回答的 token 级对数概率必须重算或按策略版本缓存，KV 复用收益随更新频率下降。这意味着“吞吐”不能只报生成吞吐，必须同时报每步的有效样本吞吐与前向 token 吞吐，否则跨方案比较会失真。显存方面，省去奖励模型参数与打分激活是实打实的收益，但缓存多版本对数概率会反向吃掉一部分；功耗与硬件档位材料未给出，B200/B300 上的具体表现不可外推。</p>\n<p>最容易被误读的是理论侧的“样本复杂度与遗憾界”。它依赖偏好模型假设与数据覆盖条件，分布偏移或长尾样本会使界失效，且材料未给出具体常数，因此不能把界换算成“多少条偏好对即可达标”的工程承诺。同理，同一偏好对重复使用次数受限以控制估计偏差，这一约束会改变有效批构成的统计性质，任何与常规 RLHF 的吞吐对比都必须声明该约束是否对齐。</p>\n<table class=\"mini\"><thead><tr><th>可比项</th><th>口径要求</th><th>不可比情形</th></tr></thead><tbody><tr><td>显存占用</td><td>含奖励模型参数与打分激活的完整链路</td><td>只报策略侧显存</td></tr><tr><td>单批延迟</td><td>声明长度分桶与长尾占比</td><td>均值延迟掩盖长尾</td></tr><tr><td>吞吐</td><td>同时报样本吞吐与前向 token 吞吐</td><td>混用生成吞吐</td></tr><tr><td>样本效率</td><td>声明偏好假设与重复使用上限</td><td>把遗憾界当工程承诺</td></tr></tbody></table>\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-54\">五十四 · 迁移的第一道关口：偏好模型假设是否成立</h3>\n<p>这套算法的可迁移性不取决于代码结构，而取决于一个隐含前提：成对偏好概率可以被写成策略对数概率之差的 sigmoid 函数。理论上的实例相关界正是在这个假设下推导出来的，一旦目标领域的偏好生成机制偏离该形式，界就不再是保守估计，而是失效。工程上判断能否迁移，先做一件事：在目标领域抽一批偏好对，用当前策略计算 <span>log π(y⁺|x) − log π(y⁻|x)</span>，看这个差值对标注一致性的区分度。若区分度接近随机，说明偏好信号并不由策略相对概率主导，迁移过去只会得到一个方差极大的梯度估计器。</p>\n<p>典型的不适用场景有三类。第一类是偏好由外部规则或验证器给出（如代码单测通过、数学答案匹配），此时偏好几乎是确定性的 0/1，sigmoid 形式退化为硬阈值，梯度加权项在错误样本上会被压到接近零，学习信号消失。第二类是长文档或多轮对话中偏好来自全局质量判断，单条回答的对数概率与人类判断之间的关联被长度、格式等混杂因素稀释。第三类是标注者之间存在系统性分歧的领域（如创意写作），偏好对本身噪声大，实例相关界里的覆盖条件难以满足。</p>\n<p>代价体现在采样预算上。若假设不成立，为达到同等胜率需要成倍增加偏好对，而每步仍要对正负回答各做一次策略前向，前向次数随批大小线性增长，采样开销直接转化为 GPU 小时。判断标准应当是：先用小批量偏好对做上述区分度检验，再决定是否投入全量训练，而不是先跑起来再看曲线。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-55\">五十五 · 换模型：策略前向成本结构决定迁移代价</h3>\n<p>迁移到不同规模的策略模型时，算法的计算形态不变，但成本结构剧变。每步需要正负回答各一次前向取对数概率，这意味着单步前向次数是 2×批大小，且反向只更新策略参数。与带奖励模型的 RLHF 相比，省掉的是奖励模型前向与独立价值网络，但省不掉策略自身的两次前向。在小模型上这部分开销可以忽略，在数十亿参数以上的模型上，它成为单步延迟的主导项。</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx 2B \\cdot t_{\\text{fwd}}(L) + t_{\\text{bwd}}(B)$$</div>\n<p>其中 <span>t_fwd(L)</span> 随回答长度 L 增长，长尾样本会显著拉高单批延迟。迁移到长上下文模型时，这个式子里的 L 分布右移，KV 缓存占用随之上升；而每轮更新后策略版本变化，缓存的 token 级对数概率必须重算，KV 复用收益随更新频率下降。工程判断是：更新越频繁，缓存越不值钱；若把更新步长调大以减少重算，又要面对估计偏差上升，这正是实例相关分析里批大小与步长需要联合设定的原因。</p>\n<p>迁移到 MoE 或大词表模型还有一层：对数概率计算需要对完整词表做归一化，词表越大，每次前向的 softmax 开销越高，且这部分开销与批大小近似线性。此时应优先做长度分桶调度稳定吞吐，把长尾样本集中到单独批次，避免它们拖垮整批的 SLO。材料未给出具体分桶阈值，工程上应以单批 P99 延迟不超目标为准则反推桶边界。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-56\">五十六 · 换领域：数据覆盖条件与分布偏移</h3>\n<p>实例相关界的另一根支柱是数据覆盖：偏好数据必须覆盖策略可能生成的高概率区域。迁移到新领域时，最常见的失败不是算法错，而是偏好数据分布与部署分布错位。例如在通用对话偏好上训练、部署到垂直客服场景，策略在新领域的生成分布落在偏好数据覆盖之外，梯度估计器在这些区域没有可靠信号，界里的常数项失效。</p>\n<p>可操作的迁移做法是分层采样而非均匀采样：按提示类型、回答长度、领域标签分层构造偏好缓冲，保证每一层都有足够样本支撑该层的相对优势估计。这与批大小设定耦合——批内若某一层样本过少，该层的梯度估计方差会主导整体方差。代价是采样复杂度上升，因为分层意味着不能简单地从偏好池里随机抽，需要维护分层索引并按层配额采样，数据管线复杂度增加。</p>\n<p>另一个领域迁移的陷阱是偏好标注口径变化。同一对回答在不同标注规范下可能给出相反标签，这种系统性偏移会让 sigmoid 加权项持续偏向某一侧，表现为训练胜率上升但人工评估不升。诊断手段是周期性在留出偏好对上评估胜率，并同时看梯度估计方差；若胜率升而方差也升，说明模型在拟合标注噪声而非真实偏好。材料未给出阈值，工程上应以方差随步数不单调上升作为警戒信号。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-57\">五十七 · 规模上限：批大小、重复使用与统计效率</h3>\n<p>这套方案没有显式的规模天花板，但有两个软上限。第一个来自同一偏好对的重复使用次数：实例相关分析要求限制重复次数以控制估计偏差，因为同一对被反复使用会让梯度估计器过拟合到该对的噪声上。数据池固定时，可用的有效更新步数被数据量除以允许重复次数所约束，这直接限制了训练规模。迁移到大数据领域时这不是问题，迁移到偏好数据稀缺的垂直领域时，它成为主要瓶颈。</p>\n<p>第二个软上限来自批大小的统计效率。批越大，梯度方差越低，但每步前向次数线性增长，单步延迟随之上升。存在一个吞吐与统计效率的折中点：批太小则每步信号噪声大、需要更多步；批太大则单步延迟超 SLO、GPU 利用率被长尾样本拖低。工程判断是先把批大小定在单步延迟可接受的上限，再用步长与重复次数上限去补统计效率，而不是反过来。</p>\n<table class=\"mini\"><thead><tr><th>迁移维度</th><th>需要改的部分</th><th>主要代价</th></tr></thead><tbody><tr><td>偏好机制偏离 sigmoid 形式</td><td>换梯度估计器或退回奖励模型路线</td><td>采样预算成倍增加</td></tr><tr><td>策略模型放大</td><td>长度分桶、缓存策略、批大小重设</td><td>单步延迟与 KV 显存上升</td></tr><tr><td>领域分布偏移</td><td>分层偏好缓冲与分层配额采样</td><td>数据管线复杂度与采样开销</td></tr><tr><td>偏好数据稀缺</td><td>限制重复使用次数、缩小更新步数</td><td>有效训练规模受限</td></tr></tbody></table>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-58\">五十八 · 量化与硬件：材料未覆盖的迁移风险</h3>\n<p>该工作未涉及 NVFP4/FP8 量化下的采样稳定性，也未给出硬件档位数据。迁移到 Blackwell 部署时，量化会改变对数概率的数值精度，而梯度加权项依赖正负对数概率之差，这个差值在量化误差下可能被压缩或翻转符号，尤其在正负回答概率接近时。工程上不能直接外推“量化后仍可训练”的结论，需要单独验证：在目标精度下重算偏好对的区分度，看差值分布是否仍能支撑 sigmoid 加权。</p>\n<p>部署侧的收益是确定的：省去奖励模型与验证器推理链路，降低显存占用与服务调度复杂度。但策略前向开销上升，需在批调度与 KV 策略间权衡。迁移到分离式预填/解码架构时，训练阶段的两次前向属于预填型负载，与在线服务的解码型负载争抢资源，应把训练采样与在线推理做资源隔离，而不是共享同一批 GPU。材料未给出并行拓扑与权重同步方案，这部分属于理论算法工作，工程落地需另行设计。</p>\n<p>最终判断落在具体机制上：这套方案的迁移成本主要由偏好模型假设的成立度和策略前向的成本结构决定，而非由算法代码决定。迁移前先做偏好区分度检验与单步延迟测算，两项都过关再谈规模；任何一项不过关，省下的奖励模型显存不足以补偿失效的统计保证。</p>\n\n<h3 id=\"paper-reinforcement-learning-from-human-fe-2024-sec-59\">五十九 · 迁移边界：奖励模型省掉之后，代价挪到了哪里</h3>\n<p>这套无模型偏好策略梯度迁到别的模型或领域，第一步要改的不是算法公式，而是<b>对数概率的取数路径</b>。梯度估计器只依赖 $\\log\\pi_\\theta(y^+|x)$ 与 $\\log\\pi_\\theta(y^-|x)$ 之差，因此任何能给出 token 级对数概率的推理栈都可承载；但每轮更新后策略参数变化，缓存的对数概率立即失效，KV 复用窗口被策略版本卡死。设更新周期为 $T_u$、单条回答平均 token 数为 $L$、批内偏好对数为 $B$，则每步前向的 token 吞吐需求近似为 $2BL/T_u$，与批大小线性相关。迁到长回答领域（代码、长文档摘要）时 $L$ 抬升，同一 $B$ 下延迟被直接放大；迁到短问答领域则相反，瓶颈从单批延迟转向偏好对重复使用带来的估计偏差。工程判断是：这套方案适合回答长度分布集中、偏好对可大量采样的场景，不适合长尾极重且偏好标注昂贵的场景。</p>\n<p>失效条件集中在两处。其一是偏好模型假设：理论界依赖成对比较能被策略间相对优势稳定解释，一旦标注者偏好随提示分布漂移（例如领域迁移后同一提示的正负回答判据改变），实例相关界中的覆盖条件被破坏，样本复杂度结论不再可迁移，此时应退回带奖励模型的链路或引入分层偏好数据。其二是量化采样稳定性：材料未给出 NVFP4/FP8 下采样与对数概率的数值实验，而 sigmoid 加权对对数概率之差的微小扰动敏感，低精度下正负差值接近零的样本会放大梯度方差。迁到 Blackwell 部署时，量化方案必须与梯度估计器联合验证，不能默认沿用推理侧的精度配置。</p>\n<p>规模上限由前向次数而非显存决定。省去奖励模型与验证器链路确实降低了显存占用与调度复杂度，但每步正负回答各一次前向使采样开销翻倍，且长尾样本拉高单批延迟，需按长度分桶调度以稳定吞吐——材料未给出分桶阈值，工程上应以批延迟的方差而非均值作为分桶依据。下表给出迁移时需要重新标定的四个接口。</p>\n<table class=\"mini\"><thead><tr><th>迁移维度</th><th>需改动项</th><th>系统代价</th></tr></thead><tbody><tr><td>模型规模</td><td>对数概率取数路径、批大小按实例界重设</td><td>前向次数随批线性增长，显存让位于算力</td></tr><tr><td>领域长度分布</td><td>长度分桶、偏好对采样配比</td><td>长尾拉高单批延迟，吞吐方差上升</td></tr><tr><td>精度部署</td><td>量化下 sigmoid 加权稳定性验证</td><td>低精度放大梯度方差，需另行标定</td></tr><tr><td>数据分布</td><td>偏好覆盖条件复核、重复使用次数上限</td><td>分布偏移使界失效，需补分层数据</td></tr></tbody></table>\n<p>结论落在具体机制上：这套方案的迁移成本不在公式，而在“每轮重算对数概率”这一约束与分桶调度的耦合。凡能接受策略版本频繁切换、且偏好对供给充足的同分布场景，可省掉奖励服务链路；凡长尾重、标注漂移或需低精度高吞吐的场景，应把奖励模型或验证器作为稳定器保留，而不是把理论界当作部署承诺。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Reinforcement Learning </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">from Human Feedb…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2024 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Reinforcement Learning … 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称，仅提及成对偏好比较数据</td></tr><tr><td>基线</td><td>材料未给出基线方法名称</td></tr><tr><td>主要结果</td><td>论文以实例相关分析给出样本复杂度与遗憾界，强调无需奖励推断即可获得可证明保…</td></tr><tr><td>消融</td><td>材料未给出消融实验细节，仅可从算法结构推断奖励模型移除与批大小设定对估计方…</td></tr><tr><td>局限</td><td>理论保证依赖偏好模型假设与数据覆盖条件，实际长尾样本与分布偏移可能破坏界；…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-reinforcement-learning-from-human-fe-2024 · 共 9 个片段</p>\n";break;}}})();
